-- Wygenerowane przez narzedzia/zbuduj_pomoc.py z pomoc/pola.txt. Nie edytuj ręcznie.
-- Skrypt jest idempotentny. Opisy zmienione ręcznie w bazie (zmienione = true)
-- nie są nadpisywane.
SELECT set_config('dm.import_pomocy', 'on', false);
ON CONFLICT (klucz) DO UPDATE SET tytul = EXCLUDED.tytul, opis = EXCLUDED.opis,
    kotwica = EXCLUDED.kotwica
WHERE NOT public.tbl_pomoc_pol.zmienione;
SELECT set_config('dm.import_pomocy', '', false);
