INSERT INTO public.tbl_pomoc_pol (klucz, tytul, opis, kotwica) VALUES
    ('element.symbol', 'Symbol', 'Nazwa elementu, pod którą go znajdziesz, np. NE555P albo R-10K-0603-1%. Jedyne pole wymagane.', 'pole-symbol'),
    ('element.kategoria', 'Kategoria', 'Miejsce elementu w drzewie kategorii. Domyślnie kategoria zaznaczona przy dodawaniu.', 'pole-kategoria'),
    ('element.producent', 'Producent', 'Nazwa producenta. Biorą ją pod uwagę wyszukiwanie i etykieta.', 'pole-producent'),
    ('element.symbol_producenta', 'Symbol producenta', 'Oznaczenie katalogowe producenta. Biorą je pod uwagę wyszukiwanie i etykieta.', 'pole-producent'),
    ('element.opis', 'Opis', 'Dowolny opis: zastosowanie, uwagi, miejsce zakupu. Opis jest przeszukiwany.', 'pole-opis'),
    ('element.wartosc', 'Wartość', 'Wartość elementu, np. 10k, 100n, 4,7u. Wpisuj ją tak jak na schematach: po niej i obudowie dopasowywane są części przy imporcie z KiCada i Eagle''a.', 'pole-wartosc'),
    ('element.jednostka', 'Jednostka', 'Jednostka wartości, np. Ω, F, H, V.', 'pole-wartosc'),
    ('element.obudowa', 'Obudowy', 'Obudowy, w których pasuje ten element, po przecinku, np. R7.5, R10, R15L. Pola nie wpisuje się ręcznie: przycisk "..." otwiera listę obudów ze słownika (zaimportowanych z Eagle). Stan magazynowy jest wspólny dla wszystkich obudów elementu. Służy do dopasowania części z projektów.', 'obudowy'),
    ('element.obudowa_wybor', 'Wybór obudów', 'Otwiera listę obudów ze słownika; zaznacz wszystkie, w których pasuje element. Przycisk "Słownik obudów..." pozwala dodać nowe obudowy lub zaimportować bibliotekę Eagle.', 'obudowy'),
    ('element.obudowa_podpowiedz', 'Podpowiedz obudowę', 'Podpowiada obudowy dla symbolu (albo symbolu producenta) elementu: z typowych elementów wczytanych z bibliotek Eagle (np. BD437G pasuje do zestawu BD437) oraz z obudowy zapisanej w katalogu. Wybrana podpowiedź jest dopisywana do pola Obudowy.', 'obudowy'),
    ('element.ilosc', 'Ilość', 'Ile sztuk masz teraz. Przy nowym elemencie zapisuje się jako przyjęcie, przy edycji zmiana trafia do historii jako korekta. Do zwykłych przyjęć i wydań użyj Ctrl+T.', 'pole-ilosc'),
    ('element.minimum', 'Stan minimalny', 'Poniżej tej liczby element jest wyróżniony na liście i trafia do raportu niskich stanów. 0 wyłącza ostrzeżenie.', 'pole-minimum'),
    ('element.cena', 'Cena jednostkowa', 'Cena jednej sztuki, z której liczona jest wartość magazynu. Niezależna od cen w sklepach.', 'pole-cena'),
    ('element.waluta', 'Waluta', 'Waluta ceny jednostkowej (PLN, EUR, USD...). Sumy w raportach są liczone osobno dla każdej waluty.', 'pole-cena'),
    ('element.datasheet', 'Datasheet', 'Adres internetowy karty katalogowej. PDF można też pobrać do katalogu dokumentów (Ctrl+K).', 'pole-datasheet'),
    ('element.zdjecie', 'Zdjęcie', 'Plik obrazu elementu. Przycisk Wybierz kopiuje go do katalogu zdjęć z Ustawień.', 'pole-zdjecie'),
    ('element.tolerancja', 'Tolerancja', 'Dopuszczalne odchylenie wartości, np. 1% albo 5%. Szereg E24 ma zwykle 5%, E48 2%, E96 1%.', 'pole-tolerancja'),
    ('element.parametry', 'Parametry', 'Pozostałe parametry techniczne jednym tekstem, np. „0,1 W; 50 V; X7R”. Pole jest przeszukiwane.', 'pole-tolerancja'),
    ('element.kontener', 'Kontener', 'Kontener lub szafka, w której leży element, np. Kontener 1. Można też wpisać cały zapis naraz, np. „Kontener 1 szufladka A1/1”: program sam rozdzieli go na kontener, szufladę i przegrodę. Podpowiada kontenery użyte wcześniej.', 'pole-miejsce'),
    ('element.szuflada', 'Szuflada', 'Oznaczenie szuflady, np. A1. Samo A1 wystarczy, kontener jest opcjonalny.', 'pole-miejsce'),
    ('element.przegroda', 'Przegroda', 'Przegroda w szufladzie (opcjonalnie), np. 1. Razem z szufladą daje A1/1.', 'pole-miejsce'),
    ('element.tagi', 'Tagi', 'Słowa kluczowe oddzielone przecinkami, np. smd, precyzyjny. Są przeszukiwane.', 'pole-tagi'),
    ('projekt.nazwa', 'Nazwa projektu', 'Nazwa projektu. Pole wymagane.', 'projekty-lista'),
    ('projekt.status', 'Status projektu', 'Planowany, w trakcie, wstrzymany lub zakończony. Zestawienie zakupów domyślnie pomija projekty zakończone.', 'pole-status-projektu'),
    ('projekt.opis', 'Opis projektu', 'Dowolna notatka o projekcie.', 'projekty-lista'),
    ('pozycja.element', 'Element', 'Element z magazynu, którego dotyczy pozycja.', 'pozycje'),
    ('pozycja.oznaczenia', 'Oznaczenia', 'Oznaczenia części ze schematu, np. R1, R2, R5-R7. Wypełniane automatycznie przy imporcie.', 'pole-oznaczenia'),
    ('pozycja.potrzebna', 'Potrzebna ilość', 'Ile sztuk wymaga projekt. Brakuje: potrzebna minus już wydana minus dostępna w magazynie.', 'pole-potrzebna'),
    ('pozycja.zamowiono', 'Już zamówiono', 'Ile sztuk zamówiono, a jeszcze nie odebrano. Można to odjąć od braków w zestawieniu zakupów.', 'pole-zamowiono'),
    ('pozycja.priorytet', 'Priorytet pozycji', 'Liczba 1-10; 1 oznacza część najważniejszą.', 'pole-priorytet-pozycji'),
    ('pozycja.uwagi', 'Uwagi', 'Dowolna notatka do pozycji, np. dopuszczalny zamiennik.', 'pole-uwagi'),
    ('sklep.nazwa', 'Nazwa sklepu', 'Nazwa sklepu. Pole wymagane. Przy wczytywaniu listy sklep o tej samej nazwie jest aktualizowany.', 'pole-nazwa-sklepu'),
    ('sklep.adres', 'Adres strony', 'Adres strony głównej sklepu, np. https://sklep.pl.', 'pole-adres-sklepu'),
    ('sklep.szablon', 'Adres wyszukiwania', 'Adres wyszukiwarki sklepu z {q} w miejscu szukanej frazy, np. https://sklep.pl/szukaj?q={q}.', 'pole-szablon'),
    ('sklep.kraj', 'Kraj', 'Kraj sklepu (informacja pomocnicza).', 'pole-kraj'),
    ('sklep.waluta', 'Waluta sklepu', 'Trzyliterowy kod waluty cen w sklepie. Obce waluty są przeliczane według kursów z listy sklepów.', 'pole-waluta-sklepu'),
    ('sklep.dostawa', 'Koszt dostawy', 'Koszt standardowej dostawy w walucie sklepu. Uwzględniany w najtańszym zestawieniu.', 'pole-dostawa'),
    ('sklep.darmowa', 'Darmowa dostawa od', 'Wartość zamówienia, od której dostawa jest darmowa. Puste: dostawa jest płatna zawsze.', 'pole-darmowa'),
    ('sklep.wzorzec', 'Wzorzec ceny', 'Zaawansowane: wyrażenie regularne z jedną grupą w nawiasie, które wyciąga cenę z kodu strony produktu. Potrzebne tylko wtedy, gdy strona nie podaje ceny w danych strukturalnych.', 'pole-wzorzec'),
    ('sklep.opis', 'Opis sklepu', 'Dowolna notatka o sklepie.', 'lista-sklepow'),
    ('sklep.priorytet', 'Priorytet sklepu', 'Od 1 (najchętniej) w górę. Przy równych cenach wygrywa sklep o niższym numerze.', 'pole-priorytet-sklepu'),
    ('sklep.aktywny', 'Sklep aktywny', 'Nieaktywne sklepy nie biorą udziału w zestawieniach zakupów.', 'lista-sklepow'),
    ('link.url', 'Adres produktu', 'Adres strony samego produktu w sklepie (nie wyszukiwarki). Z niej program odczytuje cenę.', 'pole-url-linku'),
    ('link.kod', 'Kod w sklepie', 'Numer katalogowy produktu w tym sklepie.', 'pole-kod-sklepu'),
    ('link.minimum', 'Minimalna ilość', 'Najmniejsza liczba sztuk sprzedawana przez sklep. Zestawienie nie planuje zakupu poniżej niej.', 'pole-minimum-zakupu'),
    ('polaczenie.host', 'Host', 'Adres serwera PostgreSQL, np. 192.168.1.10 albo localhost.', 'polaczenie'),
    ('polaczenie.port', 'Port', 'Port serwera PostgreSQL (domyślnie 5432).', 'polaczenie'),
    ('polaczenie.baza', 'Baza danych', 'Nazwa bazy, w której leży magazyn.', 'polaczenie'),
    ('polaczenie.uzytkownik', 'Użytkownik', 'Nazwa użytkownika PostgreSQL.', 'polaczenie'),
    ('polaczenie.haslo', 'Hasło', 'Hasło użytkownika. Zapamiętane w pliku konfiguracji jest przechowywane jako zwykły tekst.', 'polaczenie'),
    ('ustawienia.obrazki', 'Folder obrazków', 'Katalog, do którego program kopiuje zdjęcia elementów.', 'pole-folder-obrazkow'),
    ('ustawienia.pdf', 'Folder PDF', 'Katalog z pobranymi datasheetami. Nazwy plików powstają z symboli elementów.', 'pole-folder-pdf'),
    ('ustawienia.typ_kodu', 'Typ kodu', 'EAN-13, EAN-8 lub Code128. Kody służą tylko do własnego oznaczania elementów.', 'pole-typ-kodu'),
    ('ustawienia.prefiks', 'Prefiks kodu', 'Liczba na początku numeru kodu (domyślnie 20), po której program rozpoznaje własne kody przy skanowaniu.', 'pole-prefiks'),
    ('ustawienia.czcionka', 'Czcionka', 'Czcionka tekstów na etykietach: nazwa, rozmiar i styl.', 'pole-czcionka'),
    ('ustawienia.jezyk', 'Język interfejsu', 'Polski, English albo według języka systemu. Zmiana działa po ponownym uruchomieniu programu.', 'ustawienia'),
    ('ustawienia.czytnik_pdf', 'Polecenie czytnika PDF', 'Polecenie otwierające PDF (także na wybranej stronie). Symbole: %f = ścieżka pliku, %p = numer strony, %u = ścieżka zakodowana jako adres URL (spacje i polskie znaki jako %20 itd.). Cudzysłowy dawaj wokół %f i %u, nigdy wokół %p. Linux: okular --page %p "%f" albo evince -p %p "%f". Windows: "C:\Program Files\Adobe\Acrobat Reader\Reader\AcroRd32.exe" /A page=%p "%f" albo SumatraPDF.exe -page %p "%f". macOS, Skim: open "skim://%u#page=%p". macOS, Brave lub Chrome: osascript -e ''tell application "Brave Browser" to open location "file://%u#page=%p"''. Puste pole: program szuka znanego czytnika, a bez numeru strony otwiera plik domyślnym programem systemu.', 'pole-czytnik-pdf'),
    ('lista.elementy', 'Lista elementów', 'Kliknięcie nagłówka sortuje listę. Dwukrotne kliknięcie edytuje element. Ctrl+F szuka.', 'elementy'),
    ('lista.kategorie', 'Drzewo kategorii', 'Kategorie można przeciągać. F2 zmienia nazwę, Delete usuwa pustą kategorię.', 'kategorie'),
    ('lista.projekty', 'Lista projektów', 'Pomarańczowy projekt ma braki w magazynie.', 'projekty-lista'),
    ('lista.pozycje', 'Lista części projektu', 'Pomarańczowy wiersz: brakuje w magazynie. Zielony: wydano w całości.', 'pozycje'),
    ('szukaj', 'Szukaj', 'Szuka po symbolu, producencie, opisie, wartości, obudowie i tagach. Kilka słów: każde musi wystąpić.', 'wyszukiwanie'),
    ('import.duplikaty', 'Gdy symbol już jest', 'Co zrobić z elementem, którego symbol jest już w magazynie: pominąć go, dodać podaną ilość do stanu (z wpisem w historii) albo uzupełnić jego dane niepustymi polami (stan bez zmian).', 'import-elementow'),
    ('szereg.rodzaj', 'Rodzaj', 'Rezystory, kondensatory albo cewki. Zmiana rodzaju ustawia typowy zakres wartości.', 'generator-szeregow'),
    ('szereg.szereg', 'Szereg', 'Szereg wartości znormalizowanych IEC 60063: E6, E12, E24, E48 lub E96. Im wyższy, tym więcej wartości w dekadzie.', 'generator-szeregow'),
    ('szereg.od', 'Od', 'Najmniejsza wartość zakresu. Możesz pisać 4k7, 100n, 2M2 albo 10 kΩ.', 'generator-szeregow'),
    ('szereg.do', 'Do', 'Największa wartość zakresu (włącznie).', 'generator-szeregow'),
    ('szereg.tolerancja', 'Tolerancja', 'Tolerancja zapisana w każdym elemencie. Puste pole: wartość typowa dla szeregu (E12 10%, E24 5%, E48 2%, E96 1%).', 'generator-szeregow'),
    ('szereg.obudowa', 'Obudowa', 'Obudowa wszystkich elementów zestawu, np. 0603, 0805, THT. Wchodzi do symbolu i decyduje o domyślnej kategorii (SMD lub THT).', 'generator-szeregow'),
    ('szereg.moc', 'Moc', 'Dopuszczalna moc rezystorów, np. 0,1 W. Zapisywana w parametrach.', 'generator-szeregow'),
    ('szereg.napiecie', 'Napięcie', 'Napięcie pracy kondensatorów, np. 50 V. Zapisywane w parametrach.', 'generator-szeregow'),
    ('szereg.dielektryk', 'Dielektryk', 'Dielektryk kondensatorów ceramicznych, np. X7R, C0G. Zapisywany w parametrach.', 'generator-szeregow'),
    ('szereg.producent', 'Producent', 'Producent wpisywany do każdego elementu zestawu.', 'generator-szeregow'),
    ('szereg.ilosc', 'Ilość każdej', 'Stan początkowy każdej wartości. Zapisuje się w historii jako przyjęcie.', 'generator-szeregow'),
    ('szereg.minimum', 'Minimum', 'Minimalny stan każdej wartości, poniżej którego element trafia na listę braków.', 'generator-szeregow'),
    ('szereg.cena', 'Cena szt.', 'Cena sztuki, wspólna dla całego zestawu. Puste pole: bez ceny.', 'generator-szeregow'),
    ('szereg.wzor', 'Wzór symbolu', 'Wzór nazwy elementu z członami {typ} {rkm} {wartosc} {obudowa} {tol} {moc} {napiecie} {dielektryk}. Puste pole: wzór domyślny, np. R-4K7-0603-5%.', 'generator-szeregow'),
    ('szereg.kategoria', 'Kategoria', 'Ścieżka kategorii, np. Elementy bierne / Rezystory / SMD. Brakujące kategorie zostaną utworzone. Puste pole: kategoria domyślna dla rodzaju i obudowy.', 'generator-szeregow'),
    ('szereg.miejsce', 'Miejsce', 'Gdzie leży zestaw, np. Kontener 1 szufladka A1 albo A1/1.', 'generator-szeregow'),
    ('szereg.dekada', 'Szuflada na dekadę', 'Każda dekada wartości (10-99, 100-999, ...) trafia do kolejnej szuflady, licząc od podanej, np. A1, A2, A3.', 'generator-szeregow'),
    ('csv.plik', 'Plik CSV', 'Plik z elementami. Wymagana jest kolumna Symbol (albo Typ z Wartością). Separator (średnik, przecinek, tabulator) jest wykrywany.', 'import-elementow'),
    ('narzedzia.paski.liczba', 'Liczba pasków', 'Rezystory mają 3, 4, 5 lub 6 pasków. Przy 4 paskach są 2 cyfry, mnożnik i tolerancja, przy 5 trzy cyfry, a szósty pasek to współczynnik temperaturowy.', 'narzedzia-kody'),
    ('narzedzia.wartosc', 'Wartość rezystora', 'Wartość, dla której pokazać paski: 4k7, 330, 0,22, 2M2.', 'narzedzia-kody'),
    ('narzedzia.smd.kod', 'Kod SMD', 'Kod z obudowy: 472 (4,7 kΩ), 1002 (10 kΩ), 4R7, 01A (EIA-96), a dla kondensatorów 104 (100 nF).', 'narzedzia-kody'),
    ('podglad.kamera', 'Zdjęcie z kamery', 'Otwiera podgląd z kamery USB. Naciśnij „Zrób zdjęcie”, a potem „Użyj zdjęcia”: zdjęcie zostanie zapisane w katalogu zdjęć i przypisane do zaznaczonego elementu.', 'zdjecia-elementow'),
    ('element.zdjecie_kamera', 'Zdjęcie z kamery', 'Robi zdjęcie kamerą USB i wpisuje jego ścieżkę w pole Zdjęcie. Zdjęcie zostanie przypisane do elementu po zapisie formularza.', 'zdjecia-elementow'),
    ('element.z_katalogu', 'Z katalogu', 'Otwiera wyszukiwarkę katalogu elementów. Wybrana pozycja wypełnia symbol, producenta, opis, wartość, obudowę, tolerancję i parametry; ilość i miejsce uzupełniasz sam.', 'katalog-elementow'),
    ('katalog.symbol', 'Symbol (katalog)', 'Oznaczenie elementu, np. LM358. Z magazynem łączy się po symbolu lub symbolu producenta (wielkość liter nie ma znaczenia).', 'katalog-elementow'),
    ('katalog.producent', 'Producent (katalog)', 'Ten sam symbol od różnych producentów to osobne pozycje katalogu. Może być puste.', 'katalog-elementow'),
    ('katalog.opis', 'Opis (katalog)', 'Krótki opis funkcji elementu, np. Dual Op-Amp.', 'katalog-elementow'),
    ('katalog.obudowa', 'Obudowa (katalog)', 'Typ obudowy, np. DIP-8, SOT-23, TO-220.', 'katalog-elementow'),
    ('katalog.rodzina', 'Rodzina', 'Grupa do filtrowania, np. Wzmacniacze operacyjne albo Tranzystory. Można wpisać własną.', 'katalog-elementow'),
    ('katalog.datasheet', 'Datasheet (adres)', 'Adres karty katalogowej. Plik PDF można pobrać przyciskiem Pobierz datasheet i potem odczytać z niego parametry.', 'katalog-datasheet'),
    ('katalog.uwagi', 'Uwagi (katalog)', 'Dowolne własne notatki o elemencie.', 'katalog-elementow'),
    ('katalog.parametry', 'Parametry', 'Dowolne pary nazwa-wartość (napięcie, prąd, częstotliwość...). Źródło mówi, skąd parametr pochodzi: ręcznie, z CSV albo z datasheetu. Kolumna „Opis (dymek)”: wyjaśnienie, co oznacza parametr, np. dla W_amax maksymalna dopuszczalna moc strat anody. Po najechaniu myszą na nazwę lub wartość parametru pojawia się dymek z tym opisem (w oknie edycji pozycji i na liście parametrów w katalogu). Gdy pole zostawisz puste, program użyje słownika opisów parametrów zapisanego w bazie (zestaw startowy: lampy i półprzewodniki, np. W_amax, V_CE(sat), R_DS(on), h_FE). Słownik edytujesz przyciskiem „Słownik parametrów...” pod listą katalogu: możesz dodawać własne symbole, zmieniać opisy i usuwać wpisy. Dla symboli spoza słownika dymka nie będzie. Opis wpisany ręcznie ma pierwszeństwo przed słownikiem.', 'katalog-elementow'),
    ('ksiazki.szukaj', 'Szukaj książki', 'Szuka po tytule, autorze, wydawcy, ISBN, tagach i uwagach.', 'literatura'),
    ('ksiazki.szukaj_tresci', 'Szukaj w treści', 'Szuka słów w treści zaindeksowanych książek PDF (wszystkie słowa na jednej stronie, bez rozróżniania wielkości liter i polskich znaków). Zatwierdź klawiszem Enter. Dwuklik na wyniku otwiera książkę na tej stronie.', 'literatura'),
    ('ksiazki.lista', 'Lista książek', 'Twoja biblioteczka. Dwuklik zmienia dane książki. Kolumna Indeks pokazuje, ile stron książki jest w indeksie treści.', 'literatura'),
    ('ksiazki.wyniki', 'Wyniki szukania w treści', 'Książka, numer strony i fragment tekstu ze znalezionym słowem w nawiasach kwadratowych. Dwuklik otwiera plik na tej stronie.', 'literatura'),
    ('ksiazki.indeksuj', 'Indeksuj treść książek', 'Wyciąga tekst z PDF oraz EPUB (program pdftotext dla PDF) i zapisuje go w bazie, dzięki czemu działa szukanie w treści.', 'literatura'),
    ('ksiazki.pozycz', 'Pożycz / Zwrot', 'Zapisuje, komu pożyczyłeś zaznaczoną książkę i do kiedy. Ten sam przycisk przyjmuje zwrot. Książki po terminie są przypominane po uruchomieniu programu.', 'literatura'),
    ('ksiazka.plik', 'Plik książki', 'Ścieżka do pliku PDF lub EPUB. Puste pole oznacza książkę papierową. Plik nie jest kopiowany, program tylko go otwiera.', 'literatura'),
    ('ksiazka.metadane', 'Odczytaj dane z pliku', 'Wpisuje w puste pola formularza dane zapisane w pliku książki: XMP i słownik Info w PDF (tytuł, autorzy, wydawca, rok, ISBN, język, słowa kluczowe, opis) albo metadane OPF w EPUB. Wypełnione pola nie są zmieniane.', 'literatura'),
    ('ksiazka.tagi', 'Tagi książki', 'Słowa kluczowe po przecinku, np. wzmacniacze, lampy, zasilacze. Są przeszukiwane razem z tytułem i autorem.', 'literatura'),
    ('narzedzia.szukaj', 'Szukaj narzędzia', 'Szuka po nazwie, producencie, modelu, kategorii, numerze seryjnym, miejscu, uwagach, a także po osobie, której narzędzie jest pożyczone.', 'narzedzia'),
    ('narzedzia.tylko_pozyczone', 'Tylko pożyczone', 'Pokazuje tylko narzędzia, które ktoś ma teraz u siebie. Pożyczone są na liście niebieskie, a po terminie pomarańczowe.', 'narzedzia'),
    ('narzedzia.lista', 'Lista narzędzi', 'Twoje narzędzia z miejscem i statusem (u mnie albo pożyczone: komu i od kiedy). Dwuklik zmienia dane narzędzia.', 'narzedzia'),
    ('narzedzia.historia', 'Historia pożyczek', 'Wszystkie pożyczki zaznaczonego narzędzia: komu, od kiedy, termin zwrotu i data zwrotu. Wiersze po terminie są pomarańczowe.', 'narzedzia'),
    ('narzedzia.pozycz', 'Pożycz', 'Zapisuje, komu i od kiedy pożyczasz zaznaczone narzędzie. Termin zwrotu jest opcjonalny; po jego upływie program przypomina o narzędziu przy starcie.', 'narzedzia'),
    ('narzedzia.zwroc', 'Zwrócono', 'Zamyka bieżącą pożyczkę zaznaczonego narzędzia i wpisuje dzisiejszą datę zwrotu. Wpis zostaje w historii.', 'narzedzia'),
    ('narzedzie.seryjny', 'Numer seryjny', 'Numer z tabliczki znamionowej narzędzia; przydaje się przy gwarancji i zgłoszeniu kradzieży.', 'narzedzia'),
    ('narzedzie.inwentarzowy', 'Numer inwentarzowy', 'Twój własny numer narzędzia (np. z naklejki na obudowie), przydatny w warsztacie i przy pożyczaniu. Szukanie na liście znajduje też po tym numerze.', 'narzedzia'),
    ('narzedzie.instrukcja', 'Instrukcja narzędzia', 'Ścieżka do pliku PDF z instrukcją albo adres strony internetowej. Przycisk Otwórz instrukcję otwiera ją w domyślnym programie.', 'narzedzia'),
    ('narzedzie.zdjecie', 'Zdjęcie narzędzia', 'Plik z obrazem (JPG, PNG, BMP, GIF). Przycisk Wybierz kopiuje go do katalogu zdjęć programu, a Z kamery robi zdjęcie kamerą USB. Podgląd widać w panelu szczegółów.', 'narzedzia'),
    ('pozyczka.osoba', 'Komu', 'Osoba, która pożycza narzędzie lub książkę. Lista podpowiada osoby, którym już pożyczałeś, ale można wpisać nową.', 'narzedzia'),
    ('pozyczka.termin', 'Termin zwrotu', 'Data, do której przedmiot ma wrócić. Puste pole (odznacz datę) oznacza pożyczkę bez terminu.', 'narzedzia'),
    ('katalog.szukaj', 'Szukaj w katalogu', 'Szuka po symbolu, producencie, opisie, rodzinie i obudowie.', 'katalog-elementow'),
    ('katalog.filtr_rodziny', 'Rodzina (filtr)', 'Ogranicza listę do jednej rodziny elementów.', 'katalog-elementow'),
    ('katalog.tylko_magazyn', 'Tylko te, które mam', 'Pokazuje tylko pozycje katalogu, które mają odpowiednik w magazynie (ten sam symbol).', 'katalog-elementow'),
    ('katalog.lista', 'Lista katalogu', 'Zielone pozycje masz w magazynie. Dwukrotne kliknięcie otwiera edycję.', 'katalog-elementow'),
    ('katalog.do_magazynu', 'Dodaj do magazynu', 'Tworzy element w magazynie z danymi z katalogu. Pytam o ilość, miejsce i kategorię. Gdy taki symbol już jest w magazynie, nic nie zostanie dodane.', 'katalog-elementow'),
    ('katalog.ocr', 'OCR datasheetu', 'Rozpoznaje tekst w zeskanowanych datasheetach zaznaczonych pozycji (pobranych do katalogu dokumentów) programem ocrmypdf i dodaje do PDF warstwę tekstową, dzięki czemu działa „Odczytaj parametry z PDF”. Wynik może zastąpić plik (oryginał zostaje jako plik.pdf.bak) albo trafić obok jako plik_ocr.pdf. Strony z tekstem są pomijane. Wymaga ocrmypdf i Tesseracta (Ustawienia, zakładka Inne). Ta sama operacja jest w menu podręcznym listy. Gdy „Odczytaj parametry z PDF” trafi na skan, program sam zaproponuje OCR.', 'katalog-elementow'),
    ('katalog.odczyt_pdf', 'Odczytaj parametry z PDF', 'Czyta tekst datasheetu (program pdftotext) i proponuje parametry. Nic nie zapisuje bez Twojego potwierdzenia, bo odczyt to zgadywanie z tekstu.', 'katalog-datasheet'),
    ('kalk.uwe', 'Napięcie wejściowe Uwe', 'Napięcie zasilające dzielnik w woltach, np. 5 albo 12.', 'kalk-dzielnik'),
    ('kalk.uwy', 'Napięcie wyjściowe Uwy', 'Napięcie, które ma dać dzielnik, np. 3,3. Musi być mniejsze niż Uwe.', 'kalk-dzielnik'),
    ('kalk.szereg', 'Szereg', 'Szereg wartości rezystorów, z którego program dobiera wynik. E24 to typowy wybór, E96 daje dokładniejsze dopasowanie.', 'kalk-dzielnik'),
    ('kalk.r1', 'R1 (do plusa)', 'Rezystor między Uwe a wyjściem dzielnika, np. 10k.', 'kalk-dzielnik'),
    ('kalk.r2', 'R2 (do masy)', 'Rezystor między wyjściem dzielnika a masą, np. 4k7.', 'kalk-dzielnik'),
    ('kalk.uzas', 'Napięcie zasilania', 'Napięcie, którym zasilasz diodę z rezystorem, w woltach.', 'kalk-led'),
    ('kalk.uf', 'Napięcie diody Uf', 'Napięcie przewodzenia diody LED: czerwona około 2 V, niebieska i biała około 3,2 V.', 'kalk-led'),
    ('kalk.iled', 'Prąd diody', 'Prąd w miliamperach, typowo 5 do 20 mA.', 'kalk-led'),
    ('kalk.rc_r', 'Rezystancja R', 'Rezystor filtru, np. 10k.', 'kalk-rc'),
    ('kalk.rc_c', 'Pojemność C', 'Kondensator filtru, np. 100n.', 'kalk-rc'),
    ('kalk.rc_f', 'Częstotliwość fc', 'Częstotliwość graniczna, dla której dobierany jest R albo C, np. 1k albo 440.', 'kalk-rc'),
    ('kalk.zas_typ', 'Prostownik', 'Mostek (4 diody), dwie połówki (uzwojenie z odczepem i 2 diody) albo jedna połówka (1 dioda). Wpływa na częstotliwość tętnień i spadek na diodach.', 'kalk-zasilacz'),
    ('kalk.zas_siec', 'Sieć', 'Częstotliwość sieci: 50 Hz w Europie, 60 Hz w USA.', 'kalk-zasilacz'),
    ('kalk.zas_u', 'Napięcie wtórne Usek', 'Napięcie skuteczne uzwojenia wtórnego transformatora w woltach (przy odczepie: jednej połówki).', 'kalk-zasilacz'),
    ('kalk.zas_i', 'Prąd obciążenia', 'Prąd pobierany z zasilacza w amperach.', 'kalk-zasilacz'),
    ('kalk.zas_c', 'Kondensator C', 'Kondensator filtrujący za prostownikiem, np. 4700u.', 'kalk-zasilacz'),
    ('kalk.zas_wy', 'Potrzebne napięcie wyjściowe', 'Napięcie stałe, które ma być na wyjściu zasilacza, w woltach.', 'kalk-zasilacz'),
    ('kalk.zas_upp', 'Dopuszczalne tętnienia', 'Tętnienia międzyszczytowe w woltach, np. 1.', 'kalk-zasilacz'),
    ('kalk.tr_vcc', 'Zasilanie Vcc', 'Napięcie zasilania stopnia tranzystorowego w woltach.', 'kalk-tranzystor'),
    ('kalk.tr_r1', 'R1 (do plusa)', 'Rezystor dzielnika bazowego między Vcc a bazą.', 'kalk-tranzystor'),
    ('kalk.tr_r2', 'R2 (do masy)', 'Rezystor dzielnika bazowego między bazą a masą.', 'kalk-tranzystor'),
    ('kalk.tr_rc', 'RC (kolektor)', 'Rezystor w kolektorze.', 'kalk-tranzystor'),
    ('kalk.tr_re', 'RE (emiter)', 'Rezystor w emiterze. Może być puste (emiter na masie).', 'kalk-tranzystor'),
    ('kalk.tr_beta', 'Wzmocnienie β', 'Wzmocnienie prądowe tranzystora (hFE), z katalogu, np. 100.', 'kalk-tranzystor'),
    ('kalk.tr_ic', 'Prąd kolektora Ic', 'Prąd spoczynkowy w miliamperach, dla którego program dobiera rezystory.', 'kalk-tranzystor'),
    ('kalk.esr_c', 'Pojemność C', 'Pojemność kondensatora elektrolitycznego, np. 1000u.', 'kalk-esr'),
    ('kalk.esr_u', 'Napięcie znamionowe U', 'Napięcie znamionowe kondensatora w woltach; od niego zależy typowy współczynnik strat tg δ.', 'kalk-esr'),
    ('kalk.esr_i', 'Prąd tętnień', 'Opcjonalnie. Skuteczny prąd tętnień w amperach; program poda moc strat I²·ESR w kondensatorze.', 'kalk-esr'),
    ('kalk.esr_tabela', 'Tabela ESR', 'Typowy ESR przy 120 Hz w zależności od pojemności (wiersze) i napięcia znamionowego (kolumny). Pierwszy wiersz to przyjęty tg δ. Wartości orientacyjne, kartę katalogową kondensatora należy sprawdzić.', 'kalk-esr'),
    ('kalk.lm_b', 'Zasilanie B+', 'Napięcie zasilania anodowego w woltach.', 'kalk-lampa'),
    ('kalk.lm_ra', 'Opór anodowy Ra', 'Rezystor anodowy lub impedancja transformatora, np. 100k.', 'kalk-lampa'),
    ('kalk.lm_ia', 'Prąd anody Ia', 'Prąd spoczynkowy anody w miliamperach.', 'kalk-lampa'),
    ('kalk.lm_ug', 'Napięcie siatki Ug', 'Ujemne napięcie siatki sterującej w woltach, odczytane z charakterystyk lampy.', 'kalk-lampa'),
    ('kalk.lm_ig2', 'Prąd ekranu Ig2', 'Tylko dla pentody lub tetrody: prąd siatki ekranującej w miliamperach.', 'kalk-lampa'),
    ('kalk.lm_ug2', 'Napięcie ekranu Ug2', 'Tylko dla pentody lub tetrody: napięcie siatki ekranującej w woltach.', 'kalk-lampa'),
    ('kalk.lm_mi', 'Amplifikacja μ', 'Współczynnik amplifikacji lampy z katalogu (ECC83: 100).', 'kalk-lampa'),
    ('kalk.lm_rw', 'Rezystancja wewnętrzna ra', 'Rezystancja wewnętrzna anody z katalogu (ECC83: 62,5 k).', 'kalk-lampa'),
    ('kalk.lm_pa', 'Moc anody max', 'Dopuszczalna moc strat anody w watach. Program ostrzeże o przekroczeniu.', 'kalk-lampa'),
    ('kalk.lm_f', 'Dolna częstotliwość', 'Opcjonalnie. Najniższa częstotliwość, dla której dobierany jest kondensator katodowy.', 'kalk-lampa'),
    ('obudowa.nazwa', 'Obudowa (nazwa)', 'Nazwa obudowy, np. R7.5 albo TO220AH. Zapisy TO-220 i TO220 są traktowane jako ta sama obudowa.', 'obudowy'),
    ('obudowa.moc', 'Moc strat', 'Dopuszczalna moc strat obudowy w watach, np. 2,5. Pole można zostawić puste.', 'obudowy'),
    ('obudowa.napiecie', 'Dopuszczalne napięcie', 'Najwyższe dopuszczalne napięcie w woltach, np. 250. Pole można zostawić puste.', 'obudowy'),
    ('obudowa.rodzina', 'Rodzina', 'Grupa obudów z biblioteki Eagle, np. TO-220 dla TO220AH i TO220AV. Pole pomocnicze, można zostawić puste.', 'obudowy'),
    ('obudowa.wariant', 'Wariant', 'Oznaczenie wariantu obudowy, np. AH (poziomo) albo BCE (kolejność wyprowadzeń). Pole pomocnicze.', 'obudowy'),
    ('obudowa.typowe', 'Typowe elementy w obudowie', 'Symbole elementów, które w bibliotekach Eagle (zestawy devicesets) występują w zaznaczonej obudowie. Lista powstaje przy wczytywaniu biblioteki .lbr.', 'obudowy'),
    ('katalog.zdjecie', 'Zdjęcie (katalog)', 'Plik ze zdjęciem lub rysunkiem elementu. Przycisk Wybierz kopiuje plik do katalogu zdjęć programu, a przycisk Z kamery robi zdjęcie aparatem. Gdy pozycja nie ma własnego zdjęcia, program pokazuje zdjęcie pasującego elementu z magazynu.', 'katalog-elementow'),
    ('katalog.parametry_podglad', 'Podgląd parametrów', 'Parametry z indeksami dolnymi i górnymi, tak jak w katalogach: V_CE daje V z indeksem CE, V_{CE(sat)} indeks z nawiasami, m^2 i 10^-3 indeks górny. Znak \_ wpisuje dosłowny podkreślnik. Dla grup wzmocnienia tranzystorów wpisz jeden parametr hFE, np. A: 110-220; B: 200-450; C: 420-800 - elementy BC547A, BC547B i BC547C zostaną dopasowane do jednej pozycji katalogu BC547.', 'katalog-elementow'),
    ('ksiazka.bn', 'Pobierz z Biblioteki Narodowej', 'Szuka książki w katalogu Biblioteki Narodowej (data.bn.org.pl) po ISBN, a gdy ISBN jest pusty, po tytule i autorze. Przy kilku trafieniach pozwala wybrać właściwe. Wpisuje tytuł, autora, wydawcę, rok, ISBN i język; tagów, uwag i pliku nie zmienia. Wymaga połączenia z internetem.', 'literatura'),
    ('ksiazka.wydanie', 'Wydanie', 'Które to wydanie książki, np. pierwsze, drugie poprawione, 3rd edition. Tekst dowolny. Pobranie z Biblioteki Narodowej uzupełnia je z pola 250 rekordu MARC. Zapisuje się też w pliku PDF (XMP prism:Edition) poleceniem Zapisz dane do PDF.', 'literatura'),
    ('ksiazka.jezyk', 'Język książki', 'Wybierz język z listy albo wpisz własny. Pole zapisuje nazwę języka, np. polski, angielski.', 'literatura'),
    ('ksiazka.uwagi', 'Uwagi książki', 'Notatki do książki, pokazane jako sformatowany HTML (pogrubienia, listy, tabele). Dwuklik w polu (albo przycisk Edytor HTML) otwiera edytor: u góry podgląd na żywo, u dołu źródło w HTML 4. Zwykły tekst bez znaczników też jest poprawny. To samo zobaczysz w oknie Info z menu podręcznego listy książek.', 'literatura'),
    ('ksiazki.zapisz_meta', 'Zapisz dane do PDF', 'Zapisuje dane z bazy (tytuł, autor, wydawca, rok, ISBN, język, tagi, uwagi) do plików PDF zaznaczonych książek programem ExifTool, w polach XMP i słowniku Info. Dzięki temu dane wracają do pliku w postaci, którą program potrafi potem odczytać. Pola puste w bazie nie kasują danych w pliku. ExifTool zostawia obok kopię oryginału (plik.pdf_original). Wymaga zainstalowanego ExifTool.', 'literatura'),
    ('ksiazki.ocr', 'OCR', 'Rozpoznaje tekst w zeskanowanych książkach PDF programem ocrmypdf i dodaje do pliku warstwę tekstową, więc działa indeks treści i wyszukiwanie. Strony, które już mają tekst, są pomijane. Wynik może zastąpić plik (oryginał zostaje jako plik.pdf.bak) albo trafić obok jako plik_ocr.pdf. OCR dużej książki trwa kilka minut lub dłużej i można go przerwać.', 'literatura'),
    ('ustawienia.exiftool', 'Program ExifTool', 'Pełna ścieżka do programu exiftool albo sama nazwa, gdy jest w PATH; puste pole = szukanie w PATH. Windows: C:\exiftool\exiftool.exe. macOS: /opt/homebrew/bin/exiftool (Apple Silicon, Homebrew) albo /usr/local/bin/exiftool (Intel). Aplikacja uruchomiona z Findera nie widzi PATH z terminala, dlatego sama sprawdza katalogi Homebrew i zwykle pole można zostawić puste. Używany do zapisu danych książek do plików PDF.', 'pole-programy-zewnetrzne'),
    ('ustawienia.ocrmypdf', 'Program ocrmypdf', 'Pełna ścieżka do programu ocrmypdf albo sama nazwa, gdy jest w PATH; puste pole = szukanie w PATH. macOS (Homebrew: brew install ocrmypdf tesseract tesseract-lang): /opt/homebrew/bin/ocrmypdf albo /usr/local/bin/ocrmypdf. Windows: ścieżka do ocrmypdf.exe z Pythona (katalog Scripts). Wymaga Tesseracta z danymi języków (pol, eng) i Ghostscripta.', 'pole-programy-zewnetrzne'),
    ('ustawienia.ocr_jezyki', 'Języki OCR', 'Kody języków Tesseracta połączone plusem, np. pol+eng. Puste pole oznacza pol+eng.', 'pole-programy-zewnetrzne'),
    ('ustawienia.mouser_klucz', 'Klucz API Mouser', 'Klucz do wyszukiwania datasheetów w Mouser Search API (przycisk Pobierz datasheet w Katalogu). Dostajesz go mailem po wypełnieniu formularza Search API Request Form na mouser.com (po zalogowaniu na konto My Mouser; adres: mouser.com/en/MyMouser/MouserSearchApplication.aspx). Wygląda jak numer w postaci xxxxxxxx-xxxx-xxxx-xxxx-xxxxxxxxxxxx. Klucz jest zapisywany tylko w Twoim pliku config.ini na tym komputerze; nie wpisuj go do repozytorium ani nie przekazuj dalej. Puste pole: Pobierz datasheet pyta o adres pliku PDF, jak dawniej.', 'pole-mouser'),
    ('etykiety.sposob', 'Sposób drukowania', 'Drukarka systemowa drukuje przez okno drukowania systemu (arkusze A4, rolki). Zebra ZPL wysyła do drukarki Zebra (np. ZD421) gotowe polecenia ZPL: tekst i kod kreskowy generuje sama drukarka, więc wydruk jest ostry i szybki. Połączenie i rozmiar etykiety ustawiasz przyciskiem Ustawienia Zebry.', 'pole-zebra'),
    ('zebra.tryb', 'Połączenie z drukarką', 'Sieć: surowe połączenie z portem 9100 drukarki (Ethernet lub Wi-Fi). USB / drukarka w systemie: nazwa drukarki zainstalowanej w systemie (Windows: np. ZDesigner ZD421; macOS i Linux: kolejka CUPS) albo ścieżka urządzenia /dev/usb/lp0 (Linux). Tylko zapis do pliku: program zapisuje polecenia ZPL i niczego nie wysyła.', 'pole-zebra'),
    ('zebra.host', 'Adres drukarki', 'Adres IP drukarki w sieci, np. 192.168.1.50, albo jej nazwa. Adres wydrukuje drukarka po przytrzymaniu przycisku Feed (etykieta z konfiguracją sieci) albo pokaże router.', 'pole-zebra'),
    ('zebra.port', 'Port', 'Port surowego druku Zebry: 9100 (domyślny). Zmieniaj tylko wtedy, gdy drukarka została skonfigurowana inaczej.', 'pole-zebra'),
    ('zebra.drukarka', 'Drukarka w systemie', 'Wybierz drukarkę z listy albo wpisz jej nazwę. Dane są wysyłane bez sterownika graficznego (typ RAW), więc w systemie wystarczy dowolna instalacja drukarki Zebra. Na Linuksie można wpisać /dev/usb/lp0.', 'pole-zebra'),
    ('zebra.plik', 'Plik ZPL', 'Plik, do którego program zapisze polecenia ZPL zamiast wysyłać je do drukarki. Przydatne do sprawdzenia zawartości albo wysłania innym programem.', 'pole-zebra'),
    ('zebra.szerokosc', 'Szerokość etykiety', 'Szerokość etykiety w milimetrach, mierzona w poprzek głowicy drukującej. Dla etykiety 50 x 80 mm zakładanej krótszym bokiem wzdłuż rolki wpisz 80 jako szerokość i 50 jako wysokość (albo odwrotnie, zależnie od tego, jak etykieta wychodzi z drukarki).', 'pole-zebra'),
    ('zebra.wysokosc', 'Wysokość etykiety', 'Długość etykiety w milimetrach, mierzona wzdłuż rolki (kierunek wysuwania). Drukarkę skalibruj raz na dane etykiety (przycisk Feed przy włączaniu albo ZebraDesigner/Zebra Setup Utilities), żeby rozpoznawała odstęp między etykietami.', 'pole-zebra'),
    ('zebra.dpi', 'Rozdzielczość drukarki', 'Rozdzielczość głowicy: 203 dpi (standard ZD421), 300 dpi lub 600 dpi. Wpływa na przeliczenie milimetrów na kropki; zła wartość daje etykietę za małą albo za dużą.', 'pole-zebra'),
    ('zebra.polskie', 'Zamieniaj polskie litery', 'Zamienia ą, ć, ę, ł, ń, ó, ś, ź, ż oraz µ, Ω, ± i ° na znaki ASCII (a, c, ..., u, ohm, +/-, deg). Odznacz po sprawdzeniu na etykiecie próbnej, że czcionka drukarki wyświetla polskie znaki.', 'pole-zebra'),
    ('zebra.obrot', 'Obrót o 180 stopni', 'Obraca cały wydruk o 180 stopni, gdy etykiety wychodzą z drukarki odwrócone.', 'pole-zebra'),
    ('audio.napiecia', 'Napięcia U1 i U2', 'Dwa napięcia, prądy albo inne wielkości polowe. Wynik to 20·log10(U1/U2) w decybelach i ln(U1/U2) w neperach. Obie wartości muszą być większe od zera.', 'pole-audio'),
    ('audio.moce', 'Moce P1 i P2', 'Dwie moce. Wynik to 10·log10(P1/P2) w decybelach i ½·ln(P1/P2) w neperach. Obie wartości muszą być większe od zera.', 'pole-audio'),
    ('audio.miara', 'Miara liniowa', 'Stosunek dwóch wielkości (np. wzmocnienie 2×). Lista wyboru mówi, czy to stosunek napięć albo prądów (20·log10) czy mocy (10·log10).', 'pole-audio'),
    ('audio.db', 'Decybele na miarę liniową', 'Decybele zamieniane na stosunek liniowy: 10^(dB/20) dla napięć i prądów, 10^(dB/10) dla mocy.', 'pole-audio'),
    ('audio.nepery', 'Nepery i decybele', 'Dla napięć 1 Np = 8,686 dB (20/ln 10). Pole Np liczy decybele, drugie pole liczy nepery z decybeli.', 'pole-audio'),
    ('audio.riaa_rodzaj', 'Rodzaj krzywej RIAA', 'Odtwarzanie to krzywa korektora wkładki gramofonowej (stałe czasowe 3180, 318 i 75 µs), nagrywanie to krzywa odwrotna. Wartości liczone względem 1 kHz.', 'pole-audio'),
    ('audio.riaa_iec', 'Filtr IEC', 'Dodaje filtr górnoprzepustowy ok. 20 Hz (stała 7950 µs) zalecany przez IEC, ograniczający szumy rumble. Dotyczy odtwarzania.', 'pole-audio'),
    ('audio.riaa_f', 'Częstotliwość RIAA', 'Częstotliwość w hercach (można użyć k, np. 2k5); wynik pokazuje tłumienie lub wzmocnienie względem 1 kHz i przesunięcie fazy.', 'pole-audio'),
    ('audio.riaa_zakres', 'Tabela RIAA', 'Zakres i krok (co ile Hz) tabeli wartości krzywej RIAA; 0 Hz jest dozwolone. Do 2000 wierszy.', 'pole-audio'),
    ('audio.riaa_siec', 'Sieć korekcyjna RC', 'R2 i R3 to rezystory wybrane przez Ciebie; program oblicza pozostałe elementy dwóch sekcji (3180/318 µs oraz 75 µs), zaokrągla je do wybranych szeregów i podaje odchyłkę od idealnej krzywej oraz tłumienie przy 1 kHz. Wykres pokazuje krzywą idealną (niebieska) i sieć po zaokrągleniu (pomarańczowa).', 'pole-audio'),
    ('audio.uklad', 'Układ lampowy', 'Wybór układu: sprzężenie RC, wtórnik anodowy, wtórnik katodowy albo inwerter różnicowy. Pola zawierają przykładowe wartości; wyniki liczą się od razu po zmianie. Rezystancje w kΩ, pojemności w pF (Cs w nF), nachylenie Sa w mA/V.', 'pole-audio'),
    ('audio.uklad_polaryzacja', 'Polaryzacja automatyczna', 'Tylko dla sprzężenia RC: włączona oznacza rezystor katodowy Rk bez kondensatora (ujemne sprzężenie prądowe), wyłączona – polaryzację stałą. Przy automatycznej górna częstotliwość jest przybliżona.', 'pole-audio'),
    ('audio.uklad_pola', 'Dane układu i lampy', 'Wartości liczbowe układu i lampy (Sa, Ka, Rwew triody). Zależność Ka ≈ Sa·Rwew. Przecinek lub kropka jako separator dziesiętny.', 'pole-audio'),
    ('audio.uklad_lampa', 'Lampa z katalogu', '„Lampa z katalogu” wstawia Sa, Ka, Rwew i pojemności wybranej lampy do pól układu (przy pustym katalogu program proponuje lampy przykładowe). „Zapisz lampę do katalogu” zapisuje dane z pól jako pozycję w rodzinie „Lampy elektronowe” zwykłego katalogu elementów (okno Katalog, import i eksport CSV działają jak dla innych pozycji).', 'pole-audio'),
    ('grafika.obraz', 'Wczytaj obraz', 'Wczytuje obraz charakterystyki anodowej lampy (PNG, JPG, BMP, GIF), np. zeskanowaną kartę katalogową. Obraz dopasowuje się do okna; wszystkie punkty zapamiętuje w pikselach obrazu.', 'pole-grafika'),
    ('grafika.tryb', 'Skalowanie i wyniki', 'Skalowanie charakterystyk służy do ustawienia osi obrazu, a Wyniki i wyznaczanie Ra do pracy z prostą obciążenia na już skalibrowanym obrazie.', 'pole-grafika'),
    ('grafika.krok', 'Krok skalowania', 'Wybierz krok i kliknij na obrazie: punkt (0,0), czyli przecięcie osi napięcia i prądu, potem punkt na osi napięcia o znanej wartości (najlepiej daleko od zera, np. 300 V) i punkt na osi prądu o znanej wartości. Punkty można ustawiać ponownie.', 'pole-grafika'),
    ('grafika.wartosc', 'Wartość punktu skalowania', 'Napięcie punktu na osi napięcia w woltach i prąd punktu na osi prądu w miliamperach. Dłuższe odcinki dają dokładniejszą skalę.', 'pole-grafika'),
    ('grafika.skaluj', 'Skaluj', 'Liczy skalę (V i mA na piksel) z trzech punktów. Skalowanie jest osobne dla obu osi, więc nie trzeba osobno wyznaczać współczynnika proporcji obrazu. Po skalowaniu pojawia się prosta obciążenia.', 'pole-grafika'),
    ('grafika.wyniki', 'Wyniki prostej obciążenia', 'Koniec prądowy (czerwony kwadrat) i napięciowy (zielony kwadrat) przeciągasz myszą po charakterystyce. Ra klasy A = ΔUa / ΔIa, Raa klasy B = 4 Ra, moc SE klasy A = ΔUa ΔIa / 8, moc PP klasy B = 4 razy moc SE. Gdy koniec prądowy leży na osi albo na lewo od niej, napięcie przyjmowane jest jako 0 V. Koniec napięciowy nie może wejść na lewo od prądowego.', 'pole-grafika'),
    ('grafika.blokady', 'Blokady Ra i amplitudy', 'Blokada wartości Ra utrzymuje nachylenie prostej przy przesuwaniu końców. Blokada amplitudy utrzymuje różnicę prądów ΔIa. Obie razem przesuwają prostą sztywno w pionie.', 'pole-grafika'),
    ('grafika.siatka', 'Siatka kontrolna', 'Rysuje linie co podany prąd i napięcie, aby sprawdzić, czy skala zgadza się z podziałką obrazu.', 'pole-grafika'),
    ('grafika.pamax', 'Pa max', 'Rysuje niebieską krzywą mocy admisyjnej anody Ia = Pa / Ua dla podanej mocy. Jeżeli pokrywa się z krzywą mocy narysowaną przez producenta, skalowanie jest poprawne.', 'pole-grafika'),
    ('znieksz.tryb', 'Rodzaj danych', 'Prądy: wpisujesz prądy anodowe w pięciu punktach prostej obciążenia (wysterowanie +Um, +0,5 Um, 0, -0,5 Um, -Um). Odcinki: wpisujesz długości odcinków a..g zmierzone linią z podziałką na wykresie.', 'pole-znieksz'),
    ('znieksz.prady', 'Prądy Ia', 'Ia max, Ia1, Ia0, Ia2, Ia min w mA, czyli prądy w pięciu równo rozłożonych punktach prostej obciążenia (od największego do najmniejszego).', 'pole-znieksz'),
    ('znieksz.odcinki', 'Odcinki a..g', 'Długości odcinków prostej obciążenia między punktami: d, e, f, g to kolejne odcinki między pięcioma punktami, a = d+e, b = f+g, c = e+f. Dla zniekształceń drugiej i trzeciej harmonicznej wystarczą a, b, c; dla czwartej potrzebne są d, e, f, g.', 'pole-znieksz'),
    ('znieksz.wyniki', 'Wyniki zniekształceń', 'h2, h3, h4 to zawartość drugiej, trzeciej i czwartej harmonicznej względem pierwszej w procentach i decybelach; h to ich suma geometryczna.', 'pole-znieksz'),
    ('grafika.znieksz', 'Punkty zniekształceń', 'Punkty Ia1, Ia0, Ia2 dla metody pięciu rzędnych. Wykonaj dwuklik na prostej obciążenia w miejscu przecięcia z krzywymi napięcia siatki (np. -30 V, -60 V, -120 V); po dwukliku zaznaczenie przechodzi na następny punkt, a punkt można ustawić ponownie, zaznaczając go. Skrajne rzędne (Ia max i Ia min) to prądy na końcach prostej.', 'pole-grafika'),
    ('dlawik.rdzen', 'Rdzeń dławika', 'Wybierz kształtkę EI (EI102 to kolumna środkowa a = 34 mm; wymiary c, d, h wynikają z a) i grubość pakietu b, albo wpisz własne wymiary w milimetrach. Grubość blachy 0,35 mm daje mniejszy współczynnik wypełnienia żelazem niż 0,5 mm.', 'pole-dlawik'),
    ('dlawik.parametry', 'Parametry dławika', 'Wymagana indukcyjność w henrach, prąd stały w miliamperach, przenikalność magnetyczna żelaza w Gs/Oe (typowo 500), dopuszczalna indukcja od prądu stałego (zwykle 0,7 do 0,85 T) i gęstość prądu w uzwojeniu. Średnica drutu 0 oznacza dobór z gęstości prądu; wpisana wartość przelicza opór i wypełnienie okna.', 'pole-dlawik'),
    ('dlawik.wyniki', 'Wyniki dławika', 'Liczba zwojów wynika z indukcyjności, prądu, indukcji i przekroju żelaza. Szczelina to całkowita szczelina powietrzna w obwodzie (μ0·N·I/B minus reluktancja żelaza); przekładka pod kolumny to jej połowa (szczelina podwójna w rdzeniu EI). Szczelina wg Krize/ECCLab nie odejmuje żelaza i służy do porównania. Wypełnienie okna powyżej 75% oznacza, że uzwojenie się nie zmieści, poniżej 50% rdzeń nie jest optymalnie wypełniony.', 'pole-dlawik'),
    ('dlawik.suwak', 'Średnica drutu nawojowego', 'Suwak ustawia średnicę gołego drutu od 0,05 do 2,00 mm (wpisuje ją w pole Średnica drutu). Program przelicza wtedy opór, spadek napięcia i wypełnienie okna.', 'pole-dlawik'),
    ('trafosiec.zasilanie', 'Napięcie zasilania', 'Napięcie sieci zasilającej uzwojenie pierwotne, domyślnie 230 V.', 'pole-trafosiec'),
    ('trafosiec.parametry', 'Parametry transformatora sieciowego', 'Indukcja w rdzeniu B [Gs], sprawność η, gęstość prądu j [A/mm²], współczynniki wypełnienia okna miedzią i rdzenia żelazem oraz grubości przekładek i ścianki karkasu. Przycisk Wartości typowe podstawia B, η i j zalecane dla danej mocy (tablica 5 Krize''a).', 'pole-trafosiec'),
    ('trafosiec.wtorne', 'Uzwojenia wtórne', 'Napięcie [V] i prąd [A] każdego uzwojenia wtórnego, jedno uzwojenie w wierszu, np. 300 0,1 i w następnym wierszu 6,3 1,8. Liczba uzwojeń jest dowolna.', 'pole-trafosiec'),
    ('trafosiec.wyniki', 'Wyniki transformatora sieciowego', 'Moce wtórna i pierwotna, prąd pierwotny (wzór 1,1·P1/U1), wymagany i posiadany iloczyn q_o·q_z (pole okna razy przekrój żelaza), liczba zwojów pierwotnych i zapas δ w oknie rdzenia (optymalnie około 5 mm).', 'pole-trafosiec'),
    ('trafosiec.tabela', 'Tabela uzwojeń', 'Dla każdego uzwojenia: liczba zwojów, normalna średnica drutu, średnica w emalii, zwojów w warstwie, liczba warstw i grubość uzwojenia razem z przekładkami.', 'pole-trafosiec'),
    ('trafopp.typ', 'Przeznaczenie transformatora PP', 'Hi-Fi: indukcja 1000 Gs. Gitarowy: indukcja 8000 Gs (wartość przyjmowana w literaturze gitarowej dla transformatora ok. 50 W, siła nasycenia stali to 14000-20000 Gs); można ją zmienić w polu Indukcja B. Wzory Etapów 1-2 są te same, indukcja wpływa na iloczyn okno x rdzeń i przekrój rdzenia.', 'pole-trafopp'),
    ('trafopp.lampa', 'Lampa z katalogu (Transformator PP)', 'Wybór lampy mocy z katalogu (rodzina „Lampy elektronowe”, parametr „Ia0 PP [mA]”) wpisuje do wymagań jej rezystancję wewnętrzną Ri (z parametru Rwew), typowy prąd spoczynkowy I0 jednej lampy i typową impedancję Raa pary (parametr „Raa PP [Ω]”; gdy lampa go nie ma, Raa zostaje bez zmian). Na początek są EL34, 6P14P, EL84, 6V6, 6L6, ECL86, ECL82 i EBL21 (wartości orientacyjne z kart katalogowych – sprawdź dla swojego napięcia anody; część do weryfikacji, patrz uwagi pozycji). Własną lampę dodasz w katalogu z parametrami Sa, Rwew i Ia0 PP. Ręczna zmiana Ri lub I0 przywraca „(wpisz ręcznie)”.', 'pole-trafopp'),
    ('trafopp.wymiary_blachy', 'Wymiary blachy EI (PP)', 'Wymiary blachy w milimetrach: A, B (zewnętrzne), a (kolumna środkowa), c (szerokość okna), d (kolumna boczna), h (wysokość okna); grubość pakietu b jest w polu Grubość pakietu. Wybór kształtki EI wypełnia te pola, ale można je poprawić – wtedy kształtka przechodzi na „własna”. Z wymiarów program liczy przekrój S = a·b, drogę strumienia, długość zwoju, wysokość uzwojenia h i szerokość okna. Dla nietypowej blachy łatwiej zmierzyć wymiary niż liczyć te wielkości ręcznie.', 'pole-trafopp'),
    ('trafopp.wymagania', 'Wymagania transformatora PP', 'Rezystancja obciążenia, rezystancja Raa od anody do anody, moc, dolna i górna częstotliwość graniczna, rezystancja wewnętrzna lampy i prąd spoczynkowy. Z nich program liczy pożądane parametry transformatora (Etap 1).', 'pole-trafopp'),
    ('trafopp.zaawansowane', 'Parametry zaawansowane PP', 'Indukcja B, przenikalność rdzenia μ, sprawność η, współczynniki wypełnienia rdzenia i okna oraz gęstość prądu σ.', 'pole-trafopp'),
    ('trafopp.pozadane', 'Pożądane parametry PP', 'Minimalna indukcyjność pierwotna Li = (Raa∥Ri)/(2π·Fd), maksymalna indukcyjność rozproszenia Lr = (Raa+Ri)/(2π·Fg), przekładka Naa:N0 = √(Raa·η/R0), iloczyn okno x rdzeń = P0·10⁶/(4,44·Fd·α·B·β·σ) i przekrój rdzenia około √iloczynu.', 'pole-trafopp'),
    ('trafopp.rdzen', 'Zdobyty transformator PP', 'Wybierz kształtkę EI i grubość pakietu albo wpisz wymiary zdobytego rdzenia: przekrój S, drogę strumienia, długość zwoju, wysokość uzwojenia i sumę grubości uzwojeń (szerokość okna).', 'pole-trafopp'),
    ('trafopp.uzwojenia', 'Uzwojenia PP (Etap 2)', 'Liczba zwojów pierwotnych z indukcyjności Li i rdzenia, zwojów wtórnych z przekładni oraz średnice drutu z gęstości prądu. Prąd pierwotny to prąd wtórny podzielony przez przekładnię plus prąd spoczynkowy.', 'pole-trafopp'),
    ('trafopp.gitarowa', 'Porównanie: metoda gitarowa', 'Uproszczona metoda ze strony o wzmacniaczach gitarowych (guitaramplifiers.prv.pl): L1 = Ri/(ω·(1+Ri/Raa)·√(Mn²−1)) z Mn = 1,25 (spadek 2 dB), objętość rdzenia z napięcia szczytowego Um1 i indukcji, zwoje z L1 i rdzenia, prąd I1 = √(I0² + 0,25·Imax²). Wzory sprawdzone niezależnie; wynik służy tylko do porównania z naszym modelem (L1 dla −3 dB, zwoje z S·α).', 'pole-trafopp'),
    ('trafomodel.parametry', 'Parametry modelu rdzenia', 'μi i Bs opisują krzywą magnesowania żelaza (Fröhlich–Kennelly: B = μ0·μi·H/(1 + μ0·μi·H/Bs)), dodatkowa szczelina styku to resztkowa szczelina między E i I (domyślnie 0: w PP blachy składa się na przemian i szczeliny nie ma, a w SE szczelinę podajesz osobno), straty żelaza podaje producent blachy (W/kg przy 1 T i 50 Hz), spadek dB określa krańce pasma, εr to przenikalność izolacji między warstwami. Dla dokładnego wyniku zmierz indukcyjność swojego rdzenia i dobierz μi.', 'pole-trafopp'),
    ('trafomodel.wyniki', 'Wyniki analizy dokładnej', 'Jeden model dla SE i PP: indukcyjność przyrostowa z polaryzacją stałą i szczeliną (z równania amperozwojów), indukcje, pasmo z pełnej transmitancji zespolonej (Ri, Rp, Lp, straty żelaza, Cd, Lr, Rw, Rg), sprawność z miedzi i żelaza. Literatura w innych polach służy tylko do porównania.', 'pole-trafopp'),
    ('trafomodel.wykres', 'Charakterystyka pasma', 'Odpowiedź napięciowa na obciążeniu względem 1 kHz w dB (10 Hz - 1 MHz). Przerywana linia to wymagany spadek na krańcach pasma. Garb powyżej pasma to rezonans rozproszenia z pojemnością własną.', 'pole-trafopp'),
    ('trafopp.spadek', 'Spadek na krańcach pasma', 'Dopuszczalny spadek charakterystyki na dolnym i górnym krańcu pasma: 1, 2 lub 3 dB. Wpływa na wymaganą indukcyjność pierwotną Li = (Ra∥Ri)/(2π·fd·k) i dopuszczalne rozproszenie Lr = k·(Ra+Ri)/(2π·fg), gdzie k = √(M²−1), M to spadek amplitudy. Dla 3 dB (punkt połowy mocy) k = 1, dla 2 dB k = 0,765, dla 1 dB k = 0,508. Mniejszy spadek wymaga większej indukcyjności i mniejszego rozproszenia.', 'pole-trafopp'),
    ('cewka.al', 'Współczynnik AL', 'Indukcyjność właściwa rdzenia w nH na zwój kwadrat (z katalogu), L = AL·N². Producent podaje AL dla małego sygnału, bez prądu stałego, z tolerancją (np. ±25% dla ferrytów bez szczeliny).', 'pole-cewka-al'),
    ('cewka.l', 'Żądana indukcyjność', 'Indukcyjność cewki, wybierz jednostkę (µH, mH, H).', 'pole-cewka-al'),
    ('cewka.tol', 'Tolerancja AL', 'Jeśli podasz tolerancję AL w procentach, program pokaże zakres zwojów dla skrajnych wartości AL (większe AL = mniej zwojów).', 'pole-cewka-al'),
    ('cewka.sprawdz', 'Zwoje do sprawdzenia', 'Opcjonalnie: liczba zwojów, np. z innego programu. Program poda indukcyjność AL·N² dla tej liczby i jej odchyłkę od żądanej, jako porównanie.', 'pole-cewka-al'),
    ('cewka.indukcja', 'Indukcja w rdzeniu', 'Opcjonalnie: przekrój czynny Ae i prąd szczytowy. B = L·I/(N·Ae) porównywane z dopuszczalną indukcją (ferryty ok. 0,3 T); po jej przekroczeniu AL maleje i rdzeń się nasyca.', 'pole-cewka-al'),
    ('cewka.wyniki', 'Wyniki cewki z AL', 'N = √(L/AL) wynika wprost z definicji AL. Liczba zwojów jest zaokrąglana, więc podana jest indukcyjność dla zaokrąglonej liczby.', 'pole-cewka-al'),
    ('trafopp.wykonane', 'Uzwojenia wykonane', 'Całkowita liczba zwojów i normalna średnica drutu wykonanego uzwojenia pierwotnego i wtórnego. W kolumnie proponowane są wartości z Etapu 2. Z wpisanych zwojów program liczy indukcyjność pierwotną, Raa, rezystancje i rozmieszczenie w oknie.', 'pole-trafopp'),
    ('trafopp.uklad', 'Szablon układu uzwojeń', 'Gotowe układy sekcji: P-S, P/2-S-P/2, gitarowy trzysekcyjny (A 40% W 50% A 20% W 50% A 40%) oraz HiFi z karkasem dwukomorowym (jedna połowa uzwojeń w każdej komorze). Szablon wypełnia tabelę sekcji dla bieżących zwojów; tabelę możesz dowolnie zmienić (wtedy układ zmienia się na własny). Układy „Mesa Boogie DR” (odczep 4, 8 albo 16 Ω) odtwarzają dziesięciowarstwowy transformator z Rys.15 ze strony guitaramplifiers.prv.pl: pierwotne 318 + 530 + 530 + 318 zwojów (z odczepem środkowym między warstwami 4 i 7, połączenie elektryczne 1-7-4-10), wtórne w trzech grupach: warstwy 2, 5 i 8 równolegle (odczep 4 Ω), warstwy 3 i 9 równolegle (dopinka do odczepu 8 Ω) oraz warstwa 6 (dopinka do 16 Ω; 16 Ω to warstwy 2∥5∥8 plus 6, a nie plus 3∥9). Zwoje przelicza się do wpisanych z1 i z2 w proporcji 78 : 33 : 78; warstwy nieczynne dla wybranego odczepu zajmują miejsce w oknie, ale nie przewodzą. Uwaga: w oryginale każda warstwa wtórna jest nawinięta dwoma drutami równolegle, a program liczy jeden drut o średnicy z pola d2, więc liczba zwojów na warstwę i rezystancja są przybliżone.', 'pole-trafopp'),
    ('trafopp.sekcje_tabela', 'Tabela sekcji uzwojeń', 'Każdy wiersz to jedna sekcja od rdzenia na zewnątrz: A = uzwojenie pierwotne (anoda), W = wtórne, po literze numer i liczba zwojów, np. A1 600. Wiersz | oznacza przegrodę karkasu i początek następnej komory. Suma A to zwoje pierwotne, suma W wtórne. Na tej podstawie liczone są warstwy, rezystancje, rozproszenie (osobno w każdej komorze) i pojemności między warstwami oraz między uzwojeniami z rzeczywistych potencjałów (środek pierwotnego na masie, jeden koniec wtórnego na masie).', 'pole-trafopp'),
    ('trafopp.wtorne', 'Połączenie sekcji wtórnych', 'Szeregowo: napięcia sekcji się dodają. Równolegle: wszystkie sekcje W muszą mieć tę samą liczbę zwojów, równą zwojom wtórnym; rezystancja jest równoległa, a każda niesie część prądu.', 'pole-trafopp'),
    ('trafopp.scianka_karkasu', 'Ścianka karkasu', 'Grubość policzka karkasu z każdej strony okna [mm]. Zmniejsza wysokość, na której można nawinąć uzwojenie (h − 2·ścianka), a od strony rdzenia także szerokość okna. Wpisz 0, by liczyć jak dla idealnego okna bez karkasu.', 'pole-trafopp'),
    ('trafopp.margines_warstwy', 'Margines warstwy', 'Wolny pas [mm] na obu brzegach każdej warstwy, żeby drut nie zsuwał się z warstwy. Długość warstwy to wysokość komory minus dwa marginesy; od niej zależą liczba zwojów w warstwie, grubość uzwojeń i indukcyjność rozproszenia. Wpisz 0, by warstwa zajmowała całą wysokość komory.', 'pole-trafopp'),
    ('trafopp.przegroda', 'Przegroda karkasu', 'Grubość przegrody (ścianki) między komorami karkasu. Zabiera wysokość okna: każda komora ma (h − (liczba przegród)·grubość)/liczba komór.', 'pole-trafopp'),
    ('trafopp.poprawka_k', 'Poprawka k (Transformator PP)', 'Poprawka na efekty brzegowe pola rozproszenia, przez którą mnożona jest indukcyjność rozproszenia Lr (model pola jest jednowymiarowy: zakłada pole równoległe do warstw na całej wysokości, a przy końcach uzwojenia pole się rozszerza i Lr jest mniejsze). Wpisz „auto” (domyślnie) – program liczy współczynnik Rogowskiego K = 1 − δ/(π·h)·(1 − e^(−π·h/δ)) z geometrii: δ to zastępcza odległość uzwojeń z modelu pola, h – długość warstwy. Liczba większa od zera nadpisuje obliczenie (1,0 = model idealny; wartość 0,9 stosują wzory książkowe). Użyta wartość jest w wynikach jako „Użyta poprawka k”. Wzór porównawczy z książki przy „auto” używa k = 0,9. To korekta empiryczna, nie wielkość mierzona.', 'pole-trafopp'),
    ('trafopp.model', 'Parametry modelu uzwojeń', 'Przekładki między warstwami, poprawka k na efekty brzegowe pola rozproszenia (1 = model idealny, w literaturze 0,8 do 1) i rezystywność miedzi. Rozproszenie liczone jest z całki energii pola w oknie, a długość zwoju z geometrii.', 'pole-trafopp'),
    ('trafopp.wyniki3', 'Wyniki Etapu 3', 'Indukcyjność pierwotna i Raa wykonanego transformatora, rozproszenie, rezystancje i sprawność (straty w miedzi, połowa pierwotnego przewodzi przez pół okresu) oraz pole zajęte przez uzwojenia w stosunku do pola okna.', 'pole-trafopp'),
    ('trafopp.porownanie', 'Porównanie z książką i ECCLab', 'Lr wg książki i ECCLab liczone jest dla grubości uzwojeń równej szerokości okna, więc jest większe od wyniku fizycznego, który używa rzeczywistej grubości uzwojeń. Rw wg ECCLab przyjmuje długość zwoju wtórnego Cu + 1,4π·a. Wartości służą tylko do porównania.', 'pole-trafopp'),
    ('trafopp.sekcje', 'Rozmieszczenie uzwojeń', 'Sekcje od rdzenia na zewnątrz: zwoje, zwojów w warstwie, liczba warstw, grubość z przekładkami i średnia długość zwoju. Gwiazdka oznacza nieparzystą liczbę warstw.', 'pole-trafopp'),
    ('trafose.parametry', 'Parametry transformatora SE', 'Moc wyjściowa, opór anodowy Ra, opór wewnętrzny lampy Ri, prąd anodowy Ia, najniższa częstotliwość Fd i opór głośnika Rg. Indukcyjność pierwotna: Li = (Ra∥Ri)/(2π·Fd), co daje spadek 3 dB przy Fd. Przekładnia: n = √(η·Ra/Rg), bo Ra widziane z lampy to n²·Rg/η.', 'pole-trafose'),
    ('trafose.wymiary_blachy', 'Wymiary blachy EI (SE)', 'Wymiary blachy w milimetrach: A, B (zewnętrzne), a (kolumna środkowa), c (szerokość okna), d (kolumna boczna), h (wysokość okna); grubość pakietu jest w polu Grubość pakietu. Wybór kształtki EI wypełnia te pola, ale można je poprawić – wtedy kształtka przechodzi na „własna”. Z wymiarów program liczy przekrój, średnią drogę magnetyczną, długość zwoju oraz wysokość i szerokość okna.', 'pole-trafose'),
    ('trafose.rdzen', 'Rdzeń i sprawność SE', 'Sprawność η (domyślnie 0,85) oraz rdzeń: kształtka EI z grubością pakietu albo własny przekrój i średnia droga magnetyczna. Orientacyjny przekrój rdzenia to 2,5·√P [cm²].', 'pole-trafose'),
    ('trafose.karkas', 'Karkas SE (ścianka i margines)', 'Ścianka karkasu [mm]: grubość policzka z każdej strony okna i od strony rdzenia. Margines warstwy [mm]: wolny pas na obu brzegach każdej warstwy, żeby drut się nie zsuwał. Wysokość warstwy to h − 2·ścianka − 2·margines; wpływa na liczbę zwojów w warstwie, grubość uzwojeń i rozproszenie. Wpisz 0, by pominąć.', 'pole-trafose'),
    ('trafose.poprawka_k', 'Poprawka k (Transformator SE)', 'Poprawka na efekty brzegowe pola rozproszenia, przez którą mnożona jest indukcyjność rozproszenia Lr (model pola jest jednowymiarowy: zakłada pole równoległe do warstw na całej wysokości, a przy końcach uzwojenia pole się rozszerza i Lr jest mniejsze). Wpisz „auto” (domyślnie) – program liczy współczynnik Rogowskiego K = 1 − δ/(π·h)·(1 − e^(−π·h/δ)) z geometrii: δ to zastępcza odległość uzwojeń z modelu pola, h – długość warstwy. Liczba większa od zera nadpisuje obliczenie (1,0 = model idealny; wartość 0,9 stosują wzory książkowe). Użyta wartość jest w wynikach jako „Użyta poprawka k”. Wzór porównawczy z książki przy „auto” używa k = 0,9. To korekta empiryczna, nie wielkość mierzona.', 'pole-trafose'),
    ('trafose.model', 'Model fizyczny SE', 'Indukcja szczytowa B (składowa stała plus zmienna), przenikalność żelaza μ w rdzeniu ze szczeliną i gęstość prądu w uzwojeniach. Zwoje wynikają ze strumienia sprzężonego: z = L·Iszczyt/(B·S), szczelina z reluktancji: lg = μ0·S·z²/L − lFe/μ.', 'pole-trafose'),
    ('trafose.wyniki', 'Wyniki transformatora SE', 'Zwoje i średnice drutu uzwojenia pierwotnego (prąd skuteczny z prądu anodowego i składowej zmiennej) i wtórnego, szczelina całkowita oraz indukcja od prądu stałego i szczytowa. Ostrzeżenie pojawia się, gdy żądana moc przekracza możliwości lampy w klasie A.', 'pole-trafose'),
    ('trafose.porownanie', 'Porównanie z programem porównawczym', 'Program ze zrzutu liczy Li jako (Ra∥Ri)/(7,2·Fd), czyli (Ra∥Ri)/360 przy 50 Hz. Jest to o ok. 13% mniej niż Li = (Ra∥Ri)/(2π·Fd) i oznacza spadek ok. 3,6 dB przy Fd. Przekładnia w programie porównawczym √(Ra/(η·Rg)) jest większa o czynnik 1/η (24,25 zamiast 20,62 dla η = 0,85): rezystancje uzwojeń są szeregowo z obciążeniem, więc Ra = n²·Rg/η, a nie n²·Rg·η.', 'pole-trafose'),
    ('trafose.cykin', 'Porównanie z modułem Cykina', 'Podmagnesowanie z1·Ia/l w A·zw./cm: wg Cykina (XI.3) powyżej 1-2 rdzeń musi mieć szczelinę. Wynik funkcji calcSETransformer z modułu tube_magnetics (Cykin, RDH4, Morgan Jones) dla tych samych danych: stała indukcja Bdc = 0,7 T, Lp = Ra/(2π·Fd) bez Ri, przekładnia √(η·Ra/Rg) z η = 0,88, szczelina μ0·N·I/Bdc bez reluktancji żelaza. Pokazane tylko do porównania z modelem fizycznym obok.', 'pole-trafose'),
    ('trafose.spadek', 'Spadek na krańcach pasma', 'Dopuszczalny spadek charakterystyki na dolnym i górnym krańcu pasma: 1, 2 lub 3 dB. Wpływa na wymaganą indukcyjność pierwotną Li = (Ra∥Ri)/(2π·fd·k) i dopuszczalne rozproszenie Lr = k·(Ra+Ri)/(2π·fg), gdzie k = √(M²−1), M to spadek amplitudy. Dla 3 dB (punkt połowy mocy) k = 1, dla 2 dB k = 0,765, dla 1 dB k = 0,508. Mniejszy spadek wymaga większej indukcyjności i mniejszego rozproszenia.', 'pole-trafose'),
    ('trafose.wykonane', 'Uzwojenia wykonane SE', 'Całkowite zwoje i normalne średnice drutu wykonanego uzwojenia pierwotnego i wtórnego oraz szczelina całkowita. W kolumnie „proponowane” są wartości z formularza głównego. Indukcyjność, indukcje, rezystancje i rozproszenie liczone są dla wpisanych wartości.', 'pole-trafose'),
    ('trafose.uklad', 'Układ uzwojeń SE', 'Nieprzeplatane: pierwotne, wtórne. Pierwotne w dwóch częściach wokół wtórnego (P/2-S-P/2) albo wtórne w dwóch częściach wokół pierwotnego (S/2-P-S/2) zmniejszają rozproszenie. Po wybraniu układu z podziałem sprawdź, czy sekcje mają parzystą liczbę warstw.', 'pole-trafose'),
    ('trafose.sekcje', 'Rozmieszczenie uzwojeń SE', 'Sekcje od rdzenia na zewnątrz: zwoje, zwojów w warstwie, liczba warstw, grubość z przekładkami i średnia długość zwoju. Gwiazdka oznacza nieparzystą liczbę warstw.', 'pole-trafose'),
    ('trafose.krize', 'Porównanie z Krizem (transformator z podmagnesowaniem)', 'Wzory z książki Krizego (Transformatory wyjściowe): Q0·Qs = A·P (A = 20 pentoda bez sprzężenia zwrotnego, 10 pentoda ze sprzężeniem albo trioda bez, 5 trioda ze sprzężeniem), zwoje wg (23) i przybliżenie (24), w2 = n·w1 z n = √(Rg/Ra) (bez sprawności), szczelina l3 = w1·I0/8·10⁻⁵ mm (I0 w mA), drut wg (26) z r1 = Ra/2·(1 − η) i nagrzewanie wg (27). Szczelina Krizego to μ0·N·I/B dla B = 1 T bez reluktancji żelaza, więc nie uwzględnia zmiennej składowej indukcji. Pokazane tylko do porównania.', 'pole-trafose'),
    ('trafose.witort', 'Porównanie z Witortem', 'A. Witort, Amatorskie wzmacniacze elektroakustyczne (1972), rozdz. 11: przekrój rdzenia Q = (3÷5)·√P, zwoje n1 = 9000·√(L1·lr/(μr·Q)) z μr = 500 (rdzeń bez podmagnesowania, więc dla SE niedoszacowuje), L1 ≥ Ra/(6,28·fd) (sama Ra, bez Ri). Przekładnia p = √(η·Ra/Rg) jest taka sama jak w Magmass. Pokazane tylko do porównania.', 'pole-trafose'),
    ('termo.kamera', 'Kamera termowizyjna', 'Wybór kamery USB. Kamera termowizyjna (np. InfiRay T3 Pro) musi być podłączona i widoczna w systemie jak zwykła kamera. Program otwiera ją bez konwersji do RGB, żeby zobaczyć surowe dane.', 'termo'),
    ('termo.paleta', 'Paleta barw', 'Sposób pokazania temperatur: Żelazo, Tęcza, Szara albo Szara odwrócona. Skala od najzimniejszego do najgorętszego punktu w kadrze.', 'termo'),
    ('termo.uklad', 'Układ ramki', 'Automatycznie: ramka 256x384 z 2 bajtami na piksel to obraz (góra) i dane 16-bitowe (dół). Możesz wymusić inny układ, jeśli kamera przesyła dane inaczej.', 'termo'),
    ('termo.dzielnik', 'Dzielnik', 'T[°C] = surowe / dzielnik − przesunięcie. Przyjęto 64 (jednostka 1/64 K). To hipoteza: sprawdź ją znaną temperaturą (woda z lodem 0 °C, dłoń ok. 33 °C).', 'termo'),
    ('termo.offset', 'Przesunięcie [K]', 'Odejmowane od wartości w kelwinach, domyślnie 273,15. Razem z dzielnikiem pozwala dopasować przeliczenie do kamery.', 'termo'),
    ('termo.xtherm_dll', 'Biblioteka temperatur Xtherm', 'Pozwala użyć XthermDll.dll producenta modułów Xtherm (np. T3) do przeliczenia surowej klatki 384x292 na temperatury. Biblioteki nie ma w programie (nie wolno jej rozpowszechniać): pobierz SDK od producenta i wskaż plik XthermDll.dll w wersji x64 (tylko Windows). Przy trybie surowym (polecenie 8004) liczona jest każda temperatura, przy trybie YUYV (8005) środek, minimum i maksimum. Po poleceniach (np. migawka 8000) kalibracja jest wczytywana ponownie. Zalecane polecenia modułu: 8000 migawka, 8004 tryb surowy, 8005 YUYV, 8020 zakres normalny, 8021 wysoki, 80FF zapis parametrów pomiaru.', 'termo'),
    ('termo.sdk_iray', 'Sprawdź SDK IRay', 'Ładuje bibliotekę USBSDK.dll ze wskazanego pliku (SDK pobierasz sam od IRay Technology lub dostawcy modułu, program go nie zawiera; wersja x64, tylko Windows), wyświetla znalezione kamery, typ rdzenia, numery PN/SN i zakres surowych odczytów temperatury. Skala surowych liczb nie jest opisana przez producenta, więc kalibruj ją pomiarem. Ścieżka do biblioteki jest zapamiętana.', 'termo'),
    ('termo.probka', 'Zapisz próbkę', 'Zapisuje surową klatkę (.bin) i raport (.txt) do wskazanego katalogu. Pliki posłużą do ustalenia, jak dokładnie kamera przesyła temperatury. Przy załadowanej bibliotece Xtherm zapisywane są też jej temperatury (plik _xtherm.f32) oraz temperatura detektora i rdzenia: zestaw próbek z różnych scen pozwala wyznaczyć własną kalibrację.', 'termo'),
    ('termo.raport', 'Raport diagnostyczny', 'Co kamera podaje: backend, rozmiar, typ klatki, pierwsze bajty, zakres wartości i temperatury przy bieżących parametrach.', 'termo'),
    ('drut.zestawienie', 'Zestawienie drutu (waga)', 'Długość i masa drutu każdej średnicy z uzwojeń, do zakupu na wagę. Masa miedzi = π/4·d²·długość·8,96 g/cm³ (długość = zwoje × średnia długość zwoju). „Do zakupu” to miedź plus ok. 3% lakieru i 10% zapasu na odpady i wyprowadzenia - wartości orientacyjne. Uzwojenia o tej samej średnicy są sumowane.', 'pole-drut'),
    ('termo.zoom', 'Polecenie UVC zoom (hex)', 'Wartość szesnastkowa (albo kilka, oddzielonych spacją: sekwencja) wysyłana do kamery jako kontrolka UVC „Zoom absolutny”. Kamery termowizyjne typu HT-301 i Xtherm przełączają tak tryb: 8004 = dane surowe (informacja ze społeczności, niepotwierdzona dla InfiRay T3 Pro), 8000 = kalibracja. Używaj ostrożnie.', 'termo'),
    ('termo.zoom_wyslij', 'Wyślij polecenie', 'Wysyła wpisaną wartość do otwartej kamery. Na macOS bezpośrednio przez USB; wynik (kody błędów) pojawia się w polu raportu. Po przełączeniu w tryb surowy klatka ma mieć 16-bitowe odczyty zamiast obrazu szarego - zapisz próbkę.', 'termo'),
    ('termo.kalib_temp', 'Temperatura środka [°C]', 'Znana temperatura miejsca w środku obrazu, na które patrzy kamera (np. 0 dla szklanki z wodą z lodem, ok. 100 dla wrzątku; pamiętaj o emisyjności: najlepiej czarna matowa powierzchnia albo ciemna taśma). Używane przez przycisk „Dodaj punkt kalibracji”.', 'termo'),
    ('termo.kalib_dodaj', 'Dodaj punkt kalibracji', 'Zapamiętuje odczyt surowy ze środka obrazu (średnia z 9x9 pikseli) jako podaną temperaturę. Dwa punkty dają prostą odczyt → °C, więcej punktów łamaną. Po dodaniu dwóch punktów program pokazuje temperatury (oznaczone jako kalibracja użytkownika, orientacyjnie).', 'termo'),
    ('termo.kalib_czysc', 'Wyczyść kalibrację', 'Usuwa wszystkie punkty kalibracji. Odczyt sensora zależy od jego temperatury, więc po rozgrzaniu kamery kalibrację warto powtórzyć.', 'termo'),
    ('kalk.lm_typ', 'Stabilizator', 'LM317 daje napięcie dodatnie, LM337 ujemne. Wzór na napięcie jest taki sam (wartość bezwzględna); różni się tylko minimalny prąd obciążenia (LM317 ok. 3,5 mA, LM337 ok. 2,5 mA).', 'kalk-lm'),
    ('kalk.lm_uwe', 'Napięcie wejściowe', 'Wartość bezwzględna napięcia na wejściu stabilizatora. Musi być co najmniej o ok. 3 V większa niż napięcie wyjściowe.', 'kalk-lm'),
    ('kalk.lm_i', 'Prąd obciążenia', 'Prąd pobierany z wyjścia w miliamperach; z niego liczona jest moc strat (Uwe - Uwy) · I.', 'kalk-lm'),
    ('kalk.lm_r1', 'R1', 'Rezystor między wyjściem (OUT) a końcówką ADJ, zwykle 120-240 Ω. Płynie przez niego prąd Vref/R1, który wlicza się do minimalnego prądu obciążenia.', 'kalk-lm'),
    ('kalk.lm_vref', 'Vref', 'Napięcie odniesienia między OUT a ADJ; typowo 1,25 V (karty: 1,20-1,30 V, zależnie od producenta).', 'kalk-lm'),
    ('kalk.lm_iadj', 'Prąd ADJ', 'Prąd wypływający z końcówki ADJ w mikroamperach; typowo 50 µA, maks. 100 µA. Płynie przez R2 i podnosi napięcie wyjściowe.', 'kalk-lm'),
    ('kalk.lm_r2', 'R2', 'Rezystor od ADJ do masy. R2 = 0 daje napięcie wyjściowe równe Vref.', 'kalk-lm'),
    ('kalk.lm_cel', 'Potrzebne napięcie wyjściowe', 'Wartość bezwzględna żądanego napięcia wyjściowego (większa niż Vref). Program poda R2 dokładne i najbliższe z szeregu oraz napięcie, jakie z nim wyjdzie.', 'kalk-lm'),
    ('kalk.c_dk', 'Średnica karkasu', 'Średnica wewnętrzna uzwojenia (średnica karkasu lub trzpienia) w milimetrach.', 'kalk-cewka1'),
    ('kalk.c_d', 'Średnica drutu', 'Średnica drutu bez izolacji w milimetrach.', 'kalk-cewka1'),
    ('kalk.c_dz', 'Średnica z izolacją', 'Opcjonalnie. Średnica drutu razem z lakierem; puste = drut × 1,06.', 'kalk-cewka1'),
    ('kalk.c_skok', 'Skok zwojów', 'Opcjonalnie. Odstęp osi sąsiednich zwojów w milimetrach; puste = zwoje ciasno obok siebie (skok = średnica z izolacją).', 'kalk-cewka1'),
    ('kalk.c_n', 'Liczba zwojów', 'Liczba zwojów cewki.', 'kalk-cewka1'),
    ('kalk.cw_dk', 'Średnica karkasu', 'Średnica wewnętrzna uzwojenia (średnica karkasu lub trzpienia) w milimetrach.', 'kalk-cewka2'),
    ('kalk.cw_d', 'Średnica drutu', 'Średnica drutu bez izolacji w milimetrach.', 'kalk-cewka2'),
    ('kalk.cw_dz', 'Średnica z izolacją', 'Opcjonalnie. Średnica drutu razem z lakierem; puste = drut × 1,06.', 'kalk-cewka2'),
    ('kalk.cw_skok', 'Skok zwojów', 'Opcjonalnie. Odstęp osi sąsiednich zwojów w milimetrach; puste = zwoje ciasno obok siebie (skok = średnica z izolacją).', 'kalk-cewka2'),
    ('kalk.cw_n', 'Zwojów w warstwie', 'Liczba zwojów w jednej warstwie.', 'kalk-cewka2'),
    ('kalk.cw_warstwy', 'Liczba warstw', 'Liczba warstw uzwojenia (warstwa na warstwie, bez przekładek).', 'kalk-cewka2'),
    ('kalk.c_cel', 'Docelowa indukcyjność', 'Opcjonalnie. Indukcyjność w mikrohenrach; program poda najmniejszą liczbę zwojów, która ją osiąga (przy pozostałych wymiarach z formularza).', 'kalk-cewka1'),
    ('kalk.cw_cel', 'Docelowa indukcyjność', 'Opcjonalnie. Indukcyjność w mikrohenrach; program poda najmniejszą liczbę warstw, która ją osiąga (przy zwojach w warstwie z formularza).', 'kalk-cewka2'),
    ('audio.lampa_katalog', 'Lampa z katalogu (punkt pracy)', '„Lampa z katalogu” wstawia do pól punktu pracy parametry wybranej lampy: amplifikację μ (Ka), rezystancję wewnętrzną ra (Rwew) i, jeśli jest w katalogu, moc anody max (Pa max, na jedną sekcję). Pozostałe pola (B+, Ra, Ia, Ug) wpisz sam z charakterystyk lampy. Przy pustym katalogu program proponuje lampy przykładowe.', 'pole-audio'),
    ('dlawik.rdzen.wielkie_a', 'A – szerokość rdzenia', 'Całkowita szerokość blachy EI w milimetrach, mierzona w poprzek wszystkich trzech kolumn (dla kształtki EI: A = 3·a). Pole jest wypełniane z wybranej kształtki; po wpisaniu własnej wartości kształtka przełącza się na „własna”.', 'pole-dlawik'),
    ('dlawik.rdzen.wielkie_b', 'B – wysokość rdzenia', 'Całkowita wysokość blachy EI w milimetrach, od dolnej krawędzi pakietu I do górnej krawędzi pakietu E (dla kształtki EI: B = 2,5·a).', 'pole-dlawik'),
    ('dlawik.rdzen.a', 'a – kolumna środkowa', 'Szerokość środkowej kolumny rdzenia w milimetrach. To na niej leży uzwojenie, więc razem z grubością pakietu b wyznacza przekrój żelaza (a·b). Dla kształtki EI pozostałe wymiary wynikają z a.', 'pole-dlawik'),
    ('dlawik.rdzen.b', 'b – grubość pakietu', 'Grubość pakietu blach w milimetrach, czyli głębokość rdzenia prostopadle do rysunku. Razem z szerokością środkowej kolumny a daje przekrój żelaza. Po wybraniu kształtki można ją zmienić niezależnie.', 'pole-dlawik'),
    ('dlawik.rdzen.c', 'c – szerokość okna', 'Szerokość okna na uzwojenie w milimetrach, czyli odległość między kolumną środkową a boczną (dla kształtki EI: c = a/2). Okno c × h to miejsce na miedź.', 'pole-dlawik'),
    ('dlawik.rdzen.d', 'd – kolumna boczna', 'Szerokość zewnętrznej kolumny rdzenia w milimetrach (dla kształtki EI: d = a/2). Przez każdą kolumnę boczną wraca połowa strumienia, dlatego jest ona zwykle o połowę węższa od środkowej.', 'pole-dlawik'),
    ('dlawik.rdzen.h', 'h – wysokość okna', 'Wysokość okna na uzwojenie w milimetrach (dla kształtki EI: h = 1,5·a). Razem z szerokością okna c określa, ile zwojów zmieści się w rdzeniu.', 'pole-dlawik'),
    ('dlawik.rdzen.ksztaltka', 'Kształtka rdzenia', 'Typ blachy EI. Liczba w nazwie to szerokość całego rdzenia A w milimetrach (EI102: A = 102 mm, kolumna środkowa a = 34 mm). Wybór wypełnia pola A, B, a, c, d i h; „własna” pozwala wpisać wszystkie wymiary ręcznie.', 'pole-dlawik'),
    ('dlawik.rdzen.grubosc_blachy', 'Grubość blachy', 'Grubość pojedynczej blachy transformatorowej: 0,35 mm lub 0,50 mm. Cieńsza blacha ma więcej izolacji między arkuszami, więc mniejszy współczynnik wypełnienia żelazem (0,93 wobec 0,97) i nieco mniejszy przekrój czynny.', 'pole-dlawik'),
    ('dlawik.parametry.indukcyjnosc_w', 'Indukcyjność L', 'Wymagana indukcyjność dławika w henrach przy prądzie stałym podanym obok. Im większa, tym więcej zwojów i większa szczelina potrzebna, by rdzeń się nie nasycił.', 'pole-dlawik'),
    ('dlawik.parametry.natezenie_pradu', 'Prąd stały', 'Prąd stały płynący przez dławik w miliamperach (prąd obciążenia zasilacza). Prąd magnesuje rdzeń, więc decyduje o szczelinie, liczbie zwojów i grubości drutu.', 'pole-dlawik'),
    ('dlawik.parametry.przenikalnosc_magn', 'Przenikalność żelaza μ', 'Względna przenikalność magnetyczna blach w gausach na ersted (liczbowo równa przenikalności względnej). Typowo 500 przy podmagnesowaniu; używana do odjęcia reluktancji żelaza od szczeliny.', 'pole-dlawik'),
    ('dlawik.parametry.indukcja_od_pradu_stalego', 'Indukcja od prądu stałego', 'Dopuszczalna indukcja magnetyczna w rdzeniu od prądu stałego, w teslach. Zwykle 0,7–0,85 T dla blachy transformatorowej; większa wartość daje mniej zwojów, lecz rdzeń bliżej nasycenia.', 'pole-dlawik'),
    ('dlawik.parametry.gestosc_pradu', 'Gęstość prądu', 'Dopuszczalna gęstość prądu w miedzi w amperach na milimetr kwadratowy. Z niej wynika przekrój, a więc średnica drutu (gdy pole średnicy drutu zawiera 0). Typowo 2–3 A/mm².', 'pole-dlawik'),
    ('dlawik.parametry.srednica_drutu', 'Średnica drutu (wymuszona)', 'Średnica gołego drutu w milimetrach. 0 oznacza dobór z gęstości prądu; wpisana wartość przelicza opór, spadek napięcia i wypełnienie okna dla drutu, który naprawdę masz.', 'pole-dlawik'),
    ('dlawik.wyniki.zalecana_objetosc_rdzenia', 'Zalecana objętość rdzenia', 'Minimalna objętość żelaza w cm³ wg wzoru Vz = L·I²/2·10⁻³ (L w H, I w mA). Porównaj z objętością czynną rdzenia: rdzeń o mniejszej objętości będzie za mały.', 'pole-dlawik'),
    ('dlawik.wyniki.liczba_zwojow', 'Liczba zwojów', 'Liczba zwojów uzwojenia, przy której przy zadanym prądzie, indukcji i przekroju żelaza uzyskasz wymaganą indukcyjność.', 'pole-dlawik'),
    ('dlawik.wyniki.srednica_drutu', 'Średnica drutu (wynik)', 'Średnica gołego drutu w milimetrach: dobrana z gęstości prądu i zaokrąglona do 0,01 mm, albo wpisana przez Ciebie.', 'pole-dlawik'),
    ('dlawik.wyniki.szczelina', 'Szczelina', 'Całkowita szczelina powietrzna obwodu w milimetrach: μ0·N·I/B pomniejszone o reluktancję żelaza (długość drogi / μ). W rdzeniu EI występuje podwójnie, dlatego przekładka jest o połowę mniejsza.', 'pole-dlawik'),
    ('dlawik.wyniki.przekladka_pod_kolumny', 'Przekładka pod kolumny', 'Grubość przekładki (np. papier, tekstolit) w milimetrach, którą kładzie się pod kolumny skrajne rdzenia EI. Jest równa połowie całkowitej szczeliny.', 'pole-dlawik'),
    ('dlawik.wyniki.szczelina_bez_reluktancji_zelaza', 'Szczelina bez reluktancji żelaza', 'Szczelina z uproszczonego wzoru z literatury (lp = z·I/8·10⁻⁵ mm, I w mA, przeliczony na zadaną indukcję), który reluktancji żelaza nie odejmuje. Służy tylko do porównania ze szczeliną obliczoną powyżej.', 'pole-dlawik'),
    ('dlawik.wyniki.indukcyjnosc_uzyskana', 'Indukcyjność uzyskana', 'Indukcyjność w henrach, jaką naprawdę ma dławik po zaokrągleniu liczby zwojów do całkowitej i wyliczonej szczelinie.', 'pole-dlawik'),
    ('dlawik.wyniki.opornosc_uzwojenia', 'Oporność uzwojenia', 'Rezystancja stała całego uzwojenia w omach: oporność jednego metra drutu razy długość drutu (liczba zwojów × średnia długość zwoju).', 'pole-dlawik'),
    ('dlawik.wyniki.spadek_napiecia', 'Spadek napięcia', 'Spadek napięcia stałego na uzwojeniu w woltach: prąd stały razy rezystancja uzwojenia. O tyle zasilacz traci na dławiku.', 'pole-dlawik'),
    ('dlawik.wyniki.wypelnienie_okna_w', 'Wypełnienie okna', 'Jaką część okna c × h zajmuje uzwojenie wraz z izolacją emalii. Powyżej 75% uzwojenie się nie zmieści, poniżej 50% rdzeń nie jest optymalnie wykorzystany.', 'pole-dlawik'),
    ('dlawik.wyniki.dlugosc_linii_strumienia_magnetycznego', 'Długość drogi strumienia', 'Średnia droga strumienia magnetycznego w żelazie w centymetrach – dla jednej połówki rdzenia, bo strumień rozdziela się na dwie jednakowe drogi wokół okien.', 'pole-dlawik'),
    ('dlawik.wyniki.srednia_dlugosc_zwoju', 'Średnia długość zwoju', 'Długość jednego zwoju drutu w centymetrach, liczona wokół kolumny środkowej z uwzględnieniem grubości pakietu i zaokrągleń na rogach karkasu. Służy do obliczenia długości drutu i oporu.', 'pole-dlawik'),
    ('dlawik.wyniki.przekroj_czynny_rdzenia', 'Przekrój czynny rdzenia', 'Przekrój samego żelaza kolumny środkowej w cm²: szerokość a razy grubość pakietu b razy współczynnik wypełnienia żelazem blachy.', 'pole-dlawik'),
    ('dlawik.wyniki.objetosc_czynna_rdzenia', 'Objętość czynna rdzenia', 'Objętość żelaza w rdzeniu w cm³: powierzchnia blachy pomniejszona o okna, razy grubość pakietu i współczynnik wypełnienia. Porównaj ze „Zalecaną objętością rdzenia”.', 'pole-dlawik'),
    ('dlawik.wyniki.srednica_drutu_bez_emalii', 'Średnica drutu bez emalii', 'Średnica gołej miedzi w milimetrach, z której liczony jest przekrój i opór.', 'pole-dlawik'),
    ('dlawik.wyniki.srednica_drutu_w_emalii', 'Średnica drutu w emalii', 'Średnica drutu z izolacją w milimetrach (przyjęto średnicę gołą + 0,03 mm). Decyduje o tym, ile zwojów zmieści się w oknie.', 'pole-dlawik'),
    ('dlawik.wyniki.opornosc', 'Oporność drutu na metr', 'Rezystancja jednego metra drutu w omach, dla miedzi o rezystywności 1/57 Ω·mm²/m.', 'pole-dlawik'),
    ('dlawik.wyniki.liczba_zwojow_mieszczaca_sie_na_1_cm2', 'Zwojów na 1 cm²', 'Ile zwojów drutu w emalii mieści się na jednym centymetrze kwadratowym okna przy nawijaniu zwykłym (z uwzględnieniem luzów między zwojami).', 'pole-dlawik'),
    ('dlawik.wyniki.prad_dla_gestosci', 'Prąd dla zadanej gęstości', 'Prąd w miliamperach, jaki płynie w drucie o tej średnicy przy podanej gęstości prądu. Porównaj z prądem dławika.', 'pole-dlawik'),
    ('trafosiec.zasilanie.napiecie_zasilania', 'Napięcie zasilania', 'Napięcie sieci zasilającej uzwojenie pierwotne w woltach, domyślnie 230 V. Wpływa na prąd pierwotny i liczbę zwojów pierwotnych.', 'pole-trafosiec'),
    ('trafosiec.parametry.indukcja_b', 'Indukcja B', 'Indukcja w rdzeniu w gausach (1 T = 10 000 Gs). Im większa, tym mniej zwojów, ale większy prąd magnesujący i straty w żelazie. Przycisk Wartości typowe podstawia wartość zalecaną dla mocy transformatora.', 'pole-trafosiec'),
    ('trafosiec.parametry.sprawnosc', 'Sprawność η', 'Sprawność transformatora jako ułamek (np. 0,9). Moc pierwotna to moc wtórna podzielona przez sprawność. Przycisk Wartości typowe podstawia wartość zalecaną dla danej mocy.', 'pole-trafosiec'),
    ('trafosiec.parametry.gestosc_pradu_j', 'Gęstość prądu j', 'Dopuszczalna gęstość prądu w uzwojeniach w amperach na milimetr kwadratowy; z niej wynika średnica drutu każdego uzwojenia. Typowo 2–4 A/mm², mniej dla większych mocy.', 'pole-trafosiec'),
    ('trafosiec.parametry.wsp_wypelnienia_okna_cu', 'Współczynnik wypełnienia okna Cu', 'Jaką część okna rdzenia zajmuje sama miedź uzwojeń (reszta to izolacja i luzy); wchodzi do wymaganego iloczynu q_o·q_z.', 'pole-trafosiec'),
    ('trafosiec.parametry.wsp_wypelnienia_rdzenia_fe', 'Współczynnik wypełnienia rdzenia Fe', 'Jaką część przekroju kolumny zajmuje żelazo (reszta to izolacja między blachami), typowo 0,9–0,97. Pomniejsza przekrój czynny rdzenia.', 'pole-trafosiec'),
    ('trafosiec.parametry.przekladki_miedzy_warstwami', 'Przekładki między warstwami', 'Grubość papieru lub folii między kolejnymi warstwami uzwojenia w milimetrach. Zwiększa grubość uzwojenia, a więc zajęte miejsce w oknie.', 'pole-trafosiec'),
    ('trafosiec.parametry.izolacja_miedzy_uzwojeniami', 'Izolacja między uzwojeniami', 'Grubość izolacji między osobnymi uzwojeniami (np. pierwotnym i wtórnym) w milimetrach.', 'pole-trafosiec'),
    ('trafosiec.parametry.margines_warstwy', 'Margines warstwy', 'Wolny pas w milimetrach na obu brzegach każdej warstwy, żeby drut nie zsuwał się z warstwy. Wysokość nawijania to h − 2·ścianka − 2·margines; od niej zależy liczba zwojów w warstwie i grubość uzwojeń. Wpisz 0, by liczyć jak we wzorze książkowym (y = h − 2α).', 'pole-trafosiec'),
    ('trafosiec.parametry.scianka_karkasu', 'Ścianka karkasu', 'Grubość ścianki karkasu pod uzwojeniem w milimetrach; zabiera miejsce w oknie rdzenia.', 'pole-trafosiec'),
    ('trafosiec.wtorne.wpisz_uzwojenia_wtorne', 'Uzwojenia wtórne', 'Wpisz napięcie [V] i prąd [A] każdego potrzebnego uzwojenia wtórnego, jedno uzwojenie w wierszu. Przykład: wiersz „300 0,1” to uzwojenie 300 V / 0,1 A, a następny wiersz „6,3 1,8” – żarzenie 6,3 V / 1,8 A. Liczba uzwojeń jest dowolna.', 'pole-trafosiec'),
    ('trafosiec.wyniki.moc_wtorna', 'Moc wtórna', 'Suma mocy wszystkich uzwojeń wtórnych w woltoamperach (napięcie razy prąd).', 'pole-trafosiec'),
    ('trafosiec.wyniki.moc_pierwotna', 'Moc pierwotna', 'Moc pobierana z sieci w woltoamperach: moc wtórna podzielona przez sprawność.', 'pole-trafosiec'),
    ('trafosiec.wyniki.prad_pierwotny', 'Prąd pierwotny', 'Prąd uzwojenia pierwotnego w amperach, liczony wzorem 1,1·P1/U1 (1,1 uwzględnia prąd magnesujący).', 'pole-trafosiec'),
    ('trafosiec.wyniki.wymagane_q_oq_z', 'Wymagany iloczyn q_o·q_z', 'Minimalny iloczyn pola okna q_o i przekroju żelaza q_z w cm⁴, jaki musi mieć rdzeń, by pomieścił uzwojenia i nie nasycił się przy danej mocy.', 'pole-trafosiec'),
    ('trafosiec.wyniki.posiadane_q_oq_z', 'Posiadany iloczyn q_o·q_z', 'Iloczyn pola okna i przekroju żelaza wybranego rdzenia w cm⁴. Musi być nie mniejszy od wymaganego.', 'pole-trafosiec'),
    ('trafosiec.wyniki.zwoje_uzwojenia_pierwotnego', 'Zwoje uzwojenia pierwotnego', 'Liczba zwojów uzwojenia pierwotnego przy zadanym napięciu zasilania, indukcji i przekroju żelaza.', 'pole-trafosiec'),
    ('trafosiec.wyniki.zapas_w_oknie', 'Zapas w oknie δ', 'Wolne miejsce w oknie po nawinięciu wszystkich uzwojeń, w milimetrach (optymalnie około 5 mm). Wartość ujemna oznacza, że uzwojenia się nie mieszczą.', 'pole-trafosiec'),
    ('trafosiec.wyniki.przekroj_zelaza_q_z', 'Przekrój żelaza q_z', 'Przekrój czynny żelaza kolumny środkowej w cm² (szerokość a razy grubość pakietu b razy współczynnik wypełnienia rdzenia).', 'pole-trafosiec'),
    ('trafopp.wymagania.rezystancja_obciazenia_r0', 'Rezystancja obciążenia R0', 'Rezystancja obciążenia uzwojenia wtórnego w omach (np. głośnika, 4–16 Ω). Wraz z Raa wyznacza przekładnię transformatora.', 'pole-trafopp'),
    ('trafopp.wymagania.rezystancja_raa_anoda_anoda', 'Rezystancja Raa anoda-anoda', 'Rezystancja obciążenia widziana z anod obu lamp stopnia przeciwsobnego, w omach (z katalogu lampy dla wybranego punktu pracy). Wyznacza indukcyjność pierwotną i przekładnię.', 'pole-trafopp'),
    ('trafopp.wymagania.moc_wyjsciowa_p0', 'Moc wyjściowa P0', 'Moc, jaką transformator ma oddać do obciążenia, w watach. Z mocy, indukcji i częstotliwości dolnej wynika wymagany iloczyn okno × rdzeń.', 'pole-trafopp'),
    ('trafopp.wymagania.czestotliwosc_dolna_fd', 'Częstotliwość dolna Fd', 'Dolna częstotliwość graniczna pasma w hercach, przy której spadek charakterystyki ma osiągnąć wybraną wartość. Im niższa, tym większa potrzebna indukcyjność pierwotna i większy rdzeń.', 'pole-trafopp'),
    ('trafopp.wymagania.czestotliwosc_gorna_fg', 'Częstotliwość górna Fg', 'Górna częstotliwość graniczna pasma w hercach. Wyznacza maksymalną dopuszczalną indukcyjność rozproszenia uzwojeń.', 'pole-trafopp'),
    ('trafopp.wymagania.rezystancja_wewn_lampy_ri', 'Rezystancja wewnętrzna lampy Ri', 'Rezystancja wewnętrzna lampy w omach; wpływa na wymagane Li (równoległe z Raa) i dopuszczalne Lr.', 'pole-trafopp'),
    ('trafopp.wymagania.prad_spoczynkowy_i0', 'Prąd spoczynkowy I0', 'Prąd spoczynkowy lampy w miliamperach, który w stopniu przeciwsobnym się znosi; wlicza się do prądu pierwotnego i grubości drutu.', 'pole-trafopp'),
    ('trafopp.zaawansowane.indukcja_b', 'Indukcja B (zaawansowane)', 'Indukcja szczytowa w rdzeniu w gausach. Wpływa na wymagany iloczyn okno × rdzeń i przekrój rdzenia. Zmiana typu na „gitarowy” podstawia 8000 Gs.', 'pole-trafopp'),
    ('trafopp.zaawansowane.przenikalnosc_rdzenia_mi', 'Przenikalność rdzenia μ', 'Względna przenikalność magnetyczna rdzenia, używana do obliczenia liczby zwojów pierwotnych z wymaganej indukcyjności.', 'pole-trafopp'),
    ('trafopp.zaawansowane.sprawnosc', 'Sprawność η', 'Sprawność transformatora jako ułamek; wchodzi do przekładni Naa:N0 = √(Raa·η/R0).', 'pole-trafopp'),
    ('trafopp.zaawansowane.wsp_wypelnienia_rdzenia_fe', 'Współczynnik wypełnienia rdzenia Fe α', 'Jaką część geometrycznego przekroju rdzenia zajmuje żelazo (reszta to izolacja blach), typowo 0,9–0,97.', 'pole-trafopp'),
    ('trafopp.zaawansowane.wsp_wypelnienia_okna_cu', 'Współczynnik wypełnienia okna Cu β', 'Jaką część okna zajmuje miedź uzwojeń (reszta to izolacja, przekładki i luzy), typowo 0,2–0,4.', 'pole-trafopp'),
    ('trafopp.zaawansowane.gestosc_pradu', 'Gęstość prądu σ', 'Dopuszczalna gęstość prądu w uzwojeniach w A/mm²; wyznacza średnice drutów i wymagany iloczyn okno × rdzeń.', 'pole-trafopp'),
    ('trafopp.pozadane.ind_pierwotna', 'Indukcyjność pierwotna (min)', 'Minimalna indukcyjność uzwojenia pierwotnego w henrach: Li = (Raa∥Ri)/(2π·Fd·k), żeby na dolnym krańcu pasma spadek nie przekroczył wybranej wartości.', 'pole-trafopp'),
    ('trafopp.pozadane.ind_rozproszenia', 'Indukcyjność rozproszenia (max)', 'Maksymalna indukcyjność rozproszenia w henrach: Lr = k·(Raa+Ri)/(2π·Fg), żeby na górnym krańcu pasma spadek nie przekroczył wybranej wartości.', 'pole-trafopp'),
    ('trafopp.pozadane.przekladnia_naa_n0', 'Przekładnia Naa:N0', 'Stosunek liczby zwojów uzwojenia pierwotnego (anoda–anoda) do wtórnego: √(Raa·η/R0).', 'pole-trafopp'),
    ('trafopp.pozadane.okno_x_rdzen', 'Iloczyn okno × rdzeń', 'Wymagany iloczyn pola okna i przekroju rdzenia w cm⁴: P0·10⁶/(4,44·Fd·α·B·β·σ). Rdzeń o mniejszym iloczynie nie pomieści uzwojeń albo się nasyci.', 'pole-trafopp'),
    ('trafopp.pozadane.przekroj_rdzenia_okolo', 'Przekrój rdzenia około', 'Orientacyjny przekrój kolumny środkowej w cm², liczony jako pierwiastek z wymaganego iloczynu okno × rdzeń. Pomaga wybrać kształtkę.', 'pole-trafopp'),
    ('trafopp.rdzen.ksztaltka_ei', 'Kształtka EI', 'Typ blachy EI zdobytego rdzenia. Wybór podstawia przekrój, drogę strumienia, długość zwoju, wysokość uzwojenia i szerokość okna; „własna” pozwala wpisać wymiary ręcznie.', 'pole-trafopp'),
    ('trafopp.rdzen.grubosc_pakietu', 'Grubość pakietu', 'Grubość pakietu blach w milimetrach (głębokość rdzenia). Wraz ze szerokością kolumny środkowej wyznacza przekrój rdzenia.', 'pole-trafopp'),
    ('trafopp.rdzen.przekroj_rdzenia_s', 'Przekrój rdzenia S', 'Przekrój czynny rdzenia w cm² – kolumny środkowej, przez którą przechodzi cały strumień.', 'pole-trafopp'),
    ('trafopp.rdzen.droga_strumienia_fe', 'Droga strumienia Fe', 'Średnia długość drogi strumienia magnetycznego w żelazie w centymetrach.', 'pole-trafopp'),
    ('trafopp.rdzen.dlugosc_zwoju_cu', 'Długość zwoju Cu', 'Średnia długość jednego zwoju uzwojenia wokół kolumny środkowej w centymetrach; służy do obliczenia długości drutu i rezystancji.', 'pole-trafopp'),
    ('trafopp.rdzen.wysokosc_uzwojenia_h', 'Wysokość uzwojenia h', 'Wysokość (długość osiowa) okna zajmowana przez uzwojenie w centymetrach. Decyduje o liczbie zwojów w warstwie.', 'pole-trafopp'),
    ('trafopp.rdzen.suma_grubosci_uzwojen_a', 'Suma grubości uzwojeń a', 'Szerokość okna dostępna dla uzwojeń w centymetrach, od kolumny środkowej na zewnątrz. Wszystkie uzwojenia razem z przekładkami muszą się w niej zmieścić.', 'pole-trafopp'),
    ('trafopp.uzwojenia.zwoje_pierwotne', 'Zwoje pierwotne', 'Liczba zwojów uzwojenia pierwotnego (anoda–anoda) wyliczona z indukcyjności Li i parametrów rdzenia.', 'pole-trafopp'),
    ('trafopp.uzwojenia.drut_pierwotny', 'Drut pierwotny', 'Średnica drutu pierwotnego w milimetrach, dobrana z gęstości prądu i prądu pierwotnego.', 'pole-trafopp'),
    ('trafopp.uzwojenia.zwoje_wtorne', 'Zwoje wtórne', 'Liczba zwojów uzwojenia wtórnego wynikająca z przekładni Naa:N0.', 'pole-trafopp'),
    ('trafopp.uzwojenia.drut_wtorny', 'Drut wtórny', 'Średnica drutu wtórnego w milimetrach, dobrana z gęstości prądu i prądu wtórnego.', 'pole-trafopp'),
    ('trafopp.uzwojenia.prad_pierwotny', 'Prąd pierwotny', 'Prąd uzwojenia pierwotnego w amperach: prąd wtórny podzielony przez przekładnię plus prąd spoczynkowy.', 'pole-trafopp'),
    ('trafopp.uzwojenia.prad_wtorny', 'Prąd wtórny', 'Prąd uzwojenia wtórnego w amperach, wynikający z mocy wyjściowej i rezystancji obciążenia R0.', 'pole-trafopp'),
    ('trafopp.gitarowa.indukcyjnosc_l1', 'Indukcyjność L1', 'Indukcyjność pierwotna wg metody gitarowej w henrach: L1 = Ri/(ω·(1+Ri/Raa)·√(Mn²−1)), Mn = 1,25 (spadek 2 dB). Do porównania z wynikiem programu.', 'pole-trafopp'),
    ('trafopp.gitarowa.objetosc_rdzenia_vz', 'Objętość rdzenia Vż', 'Objętość rdzenia w cm³ wg metody gitarowej, liczona z napięcia szczytowego Um1 i indukcji.', 'pole-trafopp'),
    ('trafopp.gitarowa.zwoje_pierwotne', 'Zwoje pierwotne (metoda gitarowa)', 'Liczba zwojów pierwotnych wg metody gitarowej – z L1 i rdzenia. Do porównania z liczbą z modelu programu.', 'pole-trafopp'),
    ('trafopp.gitarowa.prad_skuteczny_i1', 'Prąd skuteczny I1', 'Prąd skuteczny uzwojenia pierwotnego wg metody gitarowej: I1 = √(I0² + 0,25·Imax²), w amperach.', 'pole-trafopp'),
    ('trafopp.gitarowa.drut_pierwotny', 'Drut pierwotny (metoda gitarowa)', 'Średnica drutu pierwotnego w milimetrach wg metody gitarowej; do porównania z modelem programu.', 'pole-trafopp'),
    ('trafopp.gitarowa.wtorne_4_om', 'Wtórne 4 Ω (metoda gitarowa)', 'Zwoje wtórne i średnica drutu dla obciążenia 4 Ω wg metody gitarowej: z2 = z1·√(4/(η·Raa)), d2 = d1/√(z2/z1). Podawane zawsze dla 4, 8 i 16 Ω, niezależnie od obciążenia wpisanego w wymaganiach (wzór „zwoje / drut [mm]”).', 'pole-trafopp'),
    ('trafopp.gitarowa.wtorne_8_om', 'Wtórne 8 Ω (metoda gitarowa)', 'Zwoje wtórne i średnica drutu dla obciążenia 8 Ω wg metody gitarowej: z2 = z1·√(8/(η·Raa)), d2 = d1/√(z2/z1). Podawane zawsze dla 4, 8 i 16 Ω, niezależnie od obciążenia wpisanego w wymaganiach (wzór „zwoje / drut [mm]”).', 'pole-trafopp'),
    ('trafopp.gitarowa.wtorne_16_om', 'Wtórne 16 Ω (metoda gitarowa)', 'Zwoje wtórne i średnica drutu dla obciążenia 16 Ω wg metody gitarowej: z2 = z1·√(16/(η·Raa)), d2 = d1/√(z2/z1). Podawane zawsze dla 4, 8 i 16 Ω, niezależnie od obciążenia wpisanego w wymaganiach (wzór „zwoje / drut [mm]”).', 'pole-trafopp'),
    ('trafose.parametry.przewidywana_moc_wyjsciowa', 'Przewidywana moc wyjściowa', 'Moc, jaką stopień ma oddać do głośnika, w woltoamperach. Z niej wynikają prąd szczytowy, orientacyjny przekrój rdzenia i grubość drutów.', 'pole-trafose'),
    ('trafose.parametry.opor_anodowy_lampy_ra', 'Opór anodowy lampy Ra', 'Rezystancja obciążenia anodowego lampy w omach (z katalogu lampy dla wybranego punktu pracy). Wyznacza indukcyjność pierwotną i przekładnię.', 'pole-trafose'),
    ('trafose.parametry.opor_wewnetrzny_lampy_ri', 'Opór wewnętrzny lampy Ri', 'Rezystancja wewnętrzna lampy w omach. Równolegle z Ra wyznacza wymaganą indukcyjność pierwotną: Li = (Ra∥Ri)/(2π·Fd).', 'pole-trafose'),
    ('trafose.parametry.prad_anodowy_ia', 'Prąd anodowy Ia', 'Prąd spoczynkowy anody w miliamperach, płynący przez uzwojenie pierwotne. Podmagnesowuje rdzeń, więc wymaga szczeliny, i wchodzi do prądu skutecznego uzwojenia.', 'pole-trafose'),
    ('trafose.parametry.najnizsze_pasmo_przenoszenia_fd', 'Najniższa częstotliwość pasma Fd', 'Dolna częstotliwość graniczna pasma w hercach, przy której spadek wynosi wybraną wartość (domyślnie 3 dB). Im niższa, tym większa potrzebna indukcyjność pierwotna.', 'pole-trafose'),
    ('trafose.parametry.opor_glosnika_rg', 'Opór głośnika Rg', 'Impedancja obciążenia uzwojenia wtórnego w omach (np. 4, 8 lub 16 Ω). Wraz z Ra wyznacza przekładnię transformatora.', 'pole-trafose'),
    ('trafose.rdzen.sprawnosc_transformatora', 'Sprawność transformatora η', 'Sprawność jako ułamek (domyślnie 0,85). Straty w uzwojeniach powodują, że Ra widziane z lampy to n²·Rg/η; wchodzi do przekładni.', 'pole-trafose'),
    ('trafose.rdzen.ksztaltka_ei', 'Kształtka EI', 'Typ blachy EI. Wybór podstawia przekrój rdzenia, średnią drogę magnetyczną, długość zwoju oraz wymiary okna; „własna” pozwala wpisać te wartości ręcznie.', 'pole-trafose'),
    ('trafose.rdzen.grubosc_pakietu', 'Grubość pakietu', 'Grubość pakietu blach w milimetrach (głębokość rdzenia). Wraz z szerokością kolumny środkowej wyznacza przekrój rdzenia.', 'pole-trafose'),
    ('trafose.rdzen.przekroj_rdzenia', 'Przekrój rdzenia', 'Przekrój czynny żelaza kolumny środkowej w cm². Im większy, tym mniej zwojów potrzeba przy tej samej indukcji.', 'pole-trafose'),
    ('trafose.rdzen.srednia_droga_magnetyczna', 'Średnia droga magnetyczna', 'Średnia długość drogi strumienia w żelazie w centymetrach (dla jednej połówki rdzenia EI). Wchodzi do obliczenia szczeliny: lFe/μ.', 'pole-trafose'),
    ('trafose.rdzen.dlugosc_zwoju_przy_rdzeniu', 'Długość zwoju przy rdzeniu', 'Długość jednego zwoju najbliższego rdzeniu w centymetrach. Służy do obliczenia długości drutu i rezystancji uzwojeń.', 'pole-trafose'),
    ('trafose.rdzen.wysokosc_uzwojenia', 'Wysokość uzwojenia (okna)', 'Wysokość okna dostępna na uzwojenie w centymetrach. Decyduje o liczbie zwojów w jednej warstwie.', 'pole-trafose'),
    ('trafose.rdzen.szerokosc_okna', 'Szerokość okna', 'Szerokość okna rdzenia w centymetrach – maksymalna łączna grubość uzwojeń z przekładkami.', 'pole-trafose'),
    ('trafose.model.indukcja_szczytowa_b', 'Indukcja szczytowa B', 'Maksymalna dopuszczalna indukcja w rdzeniu w teslach – suma składowej stałej od prądu anodowego i zmiennej od sygnału. Wyznacza liczbę zwojów.', 'pole-trafose'),
    ('trafose.model.przenikalnosc_zelaza_mi', 'Przenikalność żelaza μ', 'Względna przenikalność magnetyczna blach w rdzeniu ze szczeliną; używana do odjęcia reluktancji żelaza od szczeliny.', 'pole-trafose'),
    ('trafose.model.gestosc_pradu', 'Gęstość prądu σ', 'Dopuszczalna gęstość prądu w uzwojeniach w A/mm²; wyznacza średnice drutów pierwotnego i wtórnego.', 'pole-trafose'),
    ('trafose.wyniki.przekroj_rdzenia_orientacyjnie', 'Przekrój rdzenia orientacyjnie', 'Orientacyjny przekrój rdzenia w cm² wg wzoru 2,5·√P (P w VA). Do wstępnego wyboru kształtki.', 'pole-trafose'),
    ('trafose.wyniki.indukcyjnosc_pierwotna_li', 'Indukcyjność pierwotna Li', 'Wymagana indukcyjność uzwojenia pierwotnego w henrach: (Ra∥Ri)/(2π·Fd), daje spadek 3 dB przy Fd.', 'pole-trafose'),
    ('trafose.wyniki.przekladnia_n', 'Przekładnia n', 'Stosunek zwojów wtórnych do pierwotnych: n = √(η·Ra/Rg), bo Ra widziane z lampy to n²·Rg/η.', 'pole-trafose'),
    ('trafose.wyniki.prad_szczytowy', 'Prąd szczytowy', 'Szczytowy prąd uzwojenia pierwotnego w miliamperach: prąd anodowy plus amplituda składowej zmiennej.', 'pole-trafose'),
    ('trafose.wyniki.zwoje_pierwotne', 'Zwoje pierwotne', 'Liczba zwojów uzwojenia pierwotnego ze strumienia sprzężonego: z = L·I_szczyt/(B·S).', 'pole-trafose'),
    ('trafose.wyniki.drut_pierwotny', 'Drut pierwotny', 'Średnica drutu pierwotnego w milimetrach z prądu skutecznego i gęstości prądu.', 'pole-trafose'),
    ('trafose.wyniki.zwoje_wtorne', 'Zwoje wtórne', 'Liczba zwojów uzwojenia wtórnego: zwoje pierwotne razy przekładnia n.', 'pole-trafose'),
    ('trafose.wyniki.drut_wtorny', 'Drut wtórny', 'Średnica drutu wtórnego w milimetrach z prądu wtórnego i gęstości prądu.', 'pole-trafose'),
    ('trafose.wyniki.szczelina_calkowita', 'Szczelina całkowita', 'Całkowita szczelina powietrzna w milimetrach, z reluktancji: lg = μ0·S·z²/L − lFe/μ. Konieczna, bo prąd stały podmagnesowuje rdzeń.', 'pole-trafose'),
    ('trafose.wyniki.indukcja_od_pradu_stalego', 'Indukcja od prądu stałego', 'Składowa stała indukcji w rdzeniu w teslach, wytworzona przez prąd anodowy w obecności szczeliny.', 'pole-trafose'),
    ('trafose.wyniki.indukcja_szczytowa', 'Indukcja szczytowa (wynik)', 'Sumaryczna indukcja szczytowa w teslach (stała plus zmienna) dla wyliczonych zwojów i szczeliny. Nie powinna przekraczać zadanej B.', 'pole-trafose'),
    ('trafose.porownanie.li_wg_programu_porownawczego', 'Li wg programu porównawczego', 'Indukcyjność pierwotna z programu porównawczego: (Ra∥Ri)/(7,2·Fd). Do porównania z Li wyliczoną przez Magmass.', 'pole-trafose'),
    ('trafose.porownanie.n_wg_programu_porownawczego', 'n wg programu porównawczego', 'Przekładnia z programu porównawczego: √(Ra/(η·Rg)). Różni się od przekładni Magmass o czynnik 1/η. Wartość tylko do porównania.', 'pole-trafose'),
    ('trafose.cykin.zwoje_pierwotne', 'Zwoje pierwotne (Cykin)', 'Liczba zwojów pierwotnych wg modułu tube_magnetics (Cykin, RDH4, Morgan Jones) dla tych samych danych. Tylko porównanie.', 'pole-trafose'),
    ('trafose.cykin.szczelina', 'Szczelina (Cykin)', 'Szczelina w milimetrach wg modułu Cykina: μ0·N·I/Bdc bez reluktancji żelaza. Tylko porównanie.', 'pole-trafose'),
    ('trafose.cykin.indukcyjnosc_pierwotna', 'Indukcyjność pierwotna (Cykin)', 'Indukcyjność pierwotna w henrach wg modułu Cykina: Lp = Ra/(2π·Fd), bez Ri. Tylko porównanie.', 'pole-trafose'),
    ('trafose.cykin.indukcja_szczytowa_bdc_bac', 'Indukcja szczytowa Bdc+Bac (Cykin)', 'Suma indukcji stałej i zmiennej w teslach wg modułu Cykina. Tylko porównanie.', 'pole-trafose'),
    ('trafose.cykin.sprawnosc', 'Sprawność (Cykin)', 'Sprawność przyjęta w module Cykina (η = 0,88).', 'pole-trafose'),
    ('trafose.cykin.podmagnesowanie_iaz1_l', 'Podmagnesowanie Ia·z1/l', 'Iloczyn prądu anodowego i zwojów pierwotnych podzielony przez średnią drogę magnetyczną, w A·zw./cm. Wg Cykina powyżej 1–2 rdzeń musi mieć szczelinę.', 'pole-trafose'),
    ('trafose.krize.lampa_i_uklad', 'Lampa i układ (Krize, współczynnik A)', 'Rodzaj lampy i układu, od którego zależy współczynnik A we wzorze Q0·Qs = A·P: 20 – pentoda bez sprzężenia zwrotnego, 10 – pentoda ze sprzężeniem albo trioda bez, 5 – trioda ze sprzężeniem.', 'pole-trafose'),
    ('trafose.krize.zwoje_pierwotne_wzor_23', 'Zwoje pierwotne wg Krizego (23)', 'Liczba zwojów pierwotnych wg wzoru (23) z książki Krizego. Tylko porównanie.', 'pole-trafose'),
    ('trafose.krize.zwoje_pierwotne_wzor_24', 'Zwoje pierwotne wg Krizego (24)', 'Liczba zwojów pierwotnych wg przybliżenia (24) z książki Krizego. Tylko porównanie.', 'pole-trafose'),
    ('trafose.krize.zwoje_wtorne_w2_nw1', 'Zwoje wtórne wg Krizego', 'Zwoje wtórne w2 = n·w1, gdzie n = √(Rg/Ra) (bez uwzględnienia sprawności). Tylko porównanie.', 'pole-trafose'),
    ('trafose.krize.szczelina_l3_w1i0_810', 'Szczelina wg Krizego', 'Szczelina l3 = w1·I0/8·10⁻⁵ mm (I0 w mA), liczona dla B = 1 T bez odejmowania reluktancji żelaza. Tylko porównanie.', 'pole-trafose'),
    ('trafose.krize.przekladka', 'Przekładka (rdzeń płaszczowy)', 'Grubość przekładki w milimetrach między kolumnami rdzenia płaszczowego, odpowiadająca połowie szczeliny wg Krizego.', 'pole-trafose'),
    ('trafose.krize.drut_pierwotny_26', 'Drut pierwotny wg Krizego (26)', 'Średnica drutu pierwotnego w milimetrach wg wzoru (26) z r1 = Ra/2·(1 − η).', 'pole-trafose'),
    ('trafose.krize.drut_pierwotny_min_27', 'Drut pierwotny min wg Krizego (27)', 'Minimalna średnica drutu pierwotnego w milimetrach wg wzoru (27), z warunku nagrzewania.', 'pole-trafose'),
    ('trafose.krize.drut_wtorny_d1_n', 'Drut wtórny wg Krizego', 'Średnica drutu wtórnego w milimetrach: d1/√n, gdzie d1 to drut pierwotny, n – przekładnia.', 'pole-trafose'),
    ('trafose.krize.q0qs_rdzen_wymagane_ap', 'Q0·Qs wg Krizego', 'Iloczyn pola okna i przekroju żelaza rdzenia w cm⁴ oraz wymagana wartość A·P wg Krizego. Rdzeń musi mieć iloczyn nie mniejszy od wymaganego.', 'pole-trafose'),
    ('trafose.witort.przekroj_q_p', 'Przekrój Q wg Witorta', 'Przekrój rdzenia Q = (3÷5)·√P w cm² wg Witorta, „Amatorskie wzmacniacze elektroakustyczne”, rozdz. 11. Tylko porównanie.', 'pole-trafose'),
    ('trafose.witort.zwoje_n1_9000', 'Zwoje n1 wg Witorta', 'Zwoje pierwotne n1 = 9000·√(L1·lr/(μr·Q)), μr = 500 (rdzeń bez podmagnesowania, więc dla SE niedoszacowuje). Tylko porównanie.', 'pole-trafose'),
    ('trafose.witort.l1_ra', 'L1 wg Witorta', 'Wymagana indukcyjność pierwotna L1 ≥ Ra/(6,28·fd) w henrach (sama Ra, bez Ri). Tylko porównanie.', 'pole-trafose'),
    ('audio.uklad_pola.cak', 'Cak – pojemność anoda–katoda', 'Pojemność międzyelektrodowa między anodą a katodą lampy w pikofaradach (z katalogu lampy). Wchodzi do pojemności wyjściowej stopnia i do górnej częstotliwości granicznej.', 'pole-audio'),
    ('audio.uklad_pola.cas', 'Cas – pojemność anoda–siatka', 'Pojemność między anodą a siatką sterującą lampy w pikofaradach. Przez efekt Millera mnożona przez (1 + wzmocnienie) zwiększa pojemność wejściową i obniża częstotliwość górną.', 'pole-audio'),
    ('audio.uklad_pola.csk', 'Csk – pojemność siatka–katoda', 'Pojemność między siatką sterującą a katodą lampy w pikofaradach; część pojemności wejściowej stopnia.', 'pole-audio'),
    ('audio.uklad_pola.cs', 'Cs – kondensator sprzęgający', 'Pojemność kondensatora sprzęgającego stopnie, w nanofaradach. Razem z rezystancją dołączoną za nim wyznacza dolną częstotliwość graniczną.', 'pole-audio'),
    ('audio.uklad_pola.rk', 'Rk – rezystor katodowy', 'Rezystancja w obwodzie katody w kΩ. W sprzężeniu RC bez kondensatora wprowadza ujemne sprzężenie prądowe (zmniejsza wzmocnienie), w inwerterze jest wspólna dla obu katod.', 'pole-audio'),
    ('audio.uklad_pola.ra', 'Ra – rezystor anodowy', 'Rezystancja w obwodzie anody w kΩ; wraz z rezystancją wewnętrzną lampy wyznacza wzmocnienie stopnia.', 'pole-audio'),
    ('audio.uklad_pola.rs', 'Rs – rezystancja dołączona do stopnia', 'Rezystancja Rs w kΩ: obciążenie dołączone za stopniem albo rezystor w obwodzie siatki, zależnie od układu (we wtórniku anodowym wyznacza oporność wejściową, w inwerterze jest obciążeniem każdej anody).', 'pole-audio'),
    ('audio.uklad_pola.sa', 'Sa – nachylenie lampy', 'Nachylenie charakterystyki lampy w mA/V (z katalogu). Zależność: Ka ≈ Sa·Rwew. Wyznacza oporność wyjściową wtórnika katodowego (1/Sa).', 'pole-audio'),
    ('audio.uklad_pola.ka', 'Ka – współczynnik wzmocnienia lampy', 'Współczynnik wzmocnienia napięciowego lampy (amplifikacja μ), wielkość bezwymiarowa V/V (z katalogu lampy).', 'pole-audio'),
    ('audio.uklad_pola.rwew', 'Rwew – rezystancja wewnętrzna lampy', 'Rezystancja wewnętrzna triody ra w kΩ (z katalogu lub z nachylenia charakterystyki anodowej).', 'pole-audio'),
    ('audio.uklad_pola.ro', 'Ro – rezystor wyjściowy', 'Rezystancja Ro w kΩ dołączona do wyjścia wtórnika anodowego; wpływa na jego oporność wyjściową.', 'pole-audio'),
    ('audio.uklad_pola.r', 'R – rezystor wtórnika katodowego', 'Rezystor w kΩ dołączony do katody wtórnika katodowego (rezystancja obciążająca), obok Rk.', 'pole-audio'),
    ('audio.uklad_pola.ugk', 'Ugk – napięcie siatka–katoda', 'Dopuszczalne napięcie siatka–katoda w woltach. Wyznacza maksymalne napięcie wejściowe wtórnika katodowego.', 'pole-audio'),
    ('audio.uklad_pola.ka1', 'Ka1 – wzmocnienie lampy 1', 'Współczynnik wzmocnienia pierwszej lampy (górnej albo wzmacniającej) w V/V.', 'pole-audio'),
    ('audio.uklad_pola.rwew1', 'Rwew1 – rezystancja wewnętrzna lampy 1', 'Rezystancja wewnętrzna pierwszej lampy w kΩ.', 'pole-audio'),
    ('audio.uklad_pola.ka2', 'Ka2 – wzmocnienie lampy 2', 'Współczynnik wzmocnienia drugiej lampy (dolnej albo będącej źródłem prądowym) w V/V.', 'pole-audio'),
    ('audio.uklad_pola.rwew2', 'Rwew2 – rezystancja wewnętrzna lampy 2', 'Rezystancja wewnętrzna drugiej lampy w kΩ.', 'pole-audio'),
    ('audio.uklad_pola.rk2', 'Rk2 – rezystor katodowy lampy 2', 'Rezystancja w obwodzie katody drugiej lampy w kΩ; ustala jej prąd i oporność źródła prądowego.', 'pole-audio'),
    ('audio.uklad_pola.r0_obciazenie_0_brak', 'R0 – obciążenie', 'Rezystancja obciążenia wyjścia w kΩ. 0 oznacza brak obciążenia (wyjście nieobciążone).', 'pole-audio'),
    ('audio.uklad_pola.r0_obciazenie', 'R0 – obciążenie', 'Rezystancja obciążenia wyjścia w kΩ.', 'pole-audio'),
    ('audio.uklad_pola.cas1', 'Cas1 – pojemność anoda–siatka lampy 1', 'Pojemność anoda–siatka pierwszej lampy w pF (efekt Millera, pojemność wejściowa).', 'pole-audio'),
    ('audio.uklad_pola.csk1', 'Csk1 – pojemność siatka–katoda lampy 1', 'Pojemność siatka–katoda pierwszej lampy w pF; część pojemności wejściowej.', 'pole-audio'),
    ('audio.uklad_pola.cs0', 'Cs0 – pojemność obciążenia', 'Pojemność dołączona do wyjścia (kabel, następny stopień) w pF.', 'pole-audio'),
    ('audio.uklad_pola.rl_obciazenie_0_brak', 'RL – obciążenie', 'Rezystancja obciążenia SRPP w kΩ. 0 oznacza brak obciążenia.', 'pole-audio'),
    ('audio.uklad_pola.rl', 'RL – rezystor obciążenia', 'Rezystancja obciążenia wtórnika White''a w kΩ.', 'pole-audio'),
    ('audio.uklad_pola.rzad_n', 'Rząd n', 'Rząd superwtórnika, liczba całkowita od 1 do 6: im wyższy, tym mniejsza oporność wyjściowa (kolejne iteracje wtórnika).', 'pole-audio'),
    ('audio.miara.miara_liniowa', 'Miara liniowa', 'Stosunek dwóch wielkości w postaci liczby (np. 2 oznacza dwukrotne wzmocnienie). Wynik w decybelach pojawia się obok.', 'pole-audio'),
    ('audio.miara.rodzaj', 'Rodzaj miary liniowej', 'Wybór, czy miara jest stosunkiem napięć albo prądów (dB = 20·log10) czy mocy (dB = 10·log10).', 'pole-audio'),
    ('audio.db.db', 'Decybele', 'Wartość w decybelach do zamiany na miarę liniową.', 'pole-audio'),
    ('audio.db.rodzaj', 'Rodzaj miary dla decybeli', 'Wybór, czy decybele dotyczą napięć lub prądów (10^(dB/20)) czy mocy (10^(dB/10)).', 'pole-audio'),
    ('audio.nepery.np', 'Nepery', 'Wartość w neperach do zamiany na decybele: dB = 20/ln 10 · Np = 8,686 · Np.', 'pole-audio'),
    ('audio.nepery.db', 'Decybele (do neperów)', 'Wartość w decybelach do zamiany na nepery: Np = dB · ln 10/20 = dB/8,686.', 'pole-audio'),
    ('audio.napiecia.u1', 'U1', 'Pierwsze napięcie (albo prąd, albo inna wielkość polowa) – licznik stosunku U1/U2. Musi być większe od zera.', 'pole-audio'),
    ('audio.napiecia.u2', 'U2', 'Drugie napięcie (albo prąd) – mianownik stosunku U1/U2. Musi być większe od zera.', 'pole-audio'),
    ('audio.moce.p1', 'P1', 'Pierwsza moc – licznik stosunku P1/P2. Musi być większa od zera.', 'pole-audio'),
    ('audio.moce.p2', 'P2', 'Druga moc – mianownik stosunku P1/P2. Musi być większa od zera.', 'pole-audio'),
    ('audio.riaa_zakres.tabela_od', 'Tabela od', 'Pierwsza częstotliwość tabeli krzywej RIAA w hercach (0 Hz jest dozwolone).', 'pole-audio'),
    ('audio.riaa_zakres.do', 'Tabela do', 'Ostatnia częstotliwość tabeli krzywej RIAA w hercach.', 'pole-audio'),
    ('audio.riaa_zakres.co', 'Krok tabeli', 'Odstęp między kolejnymi częstotliwościami w tabeli, w hercach. Tabela ma najwyżej 2000 wierszy.', 'pole-audio'),
    ('audio.riaa_tabela', 'Tabela krzywej RIAA', 'Wartości krzywej dla kolejnych częstotliwości: tłumienie lub wzmocnienie w decybelach względem 1 kHz i przesunięcie fazy w stopniach.', 'pole-audio'),
    ('audio.riaa_siec.r2', 'R2', 'Rezystor R2 sekcji A sieci korekcyjnej, wybrany przez Ciebie. Z niego program wylicza R1, C1 i C2 (stałe czasowe 3180 i 318 µs).', 'pole-audio'),
    ('audio.riaa_siec.r3', 'R3', 'Rezystor R3 sekcji B sieci korekcyjnej, wybrany przez Ciebie. Z niego program wylicza C3 (stała czasowa 75 µs).', 'pole-audio'),
    ('audio.riaa_siec.szereg_rezystorow', 'Szereg rezystorów', 'Szereg wartości (E6…E96), do którego zaokrąglane są obliczone rezystory sieci. Gęstszy szereg daje mniejszą odchyłkę od idealnej krzywej.', 'pole-audio'),
    ('audio.riaa_siec.szereg_kondensatorow', 'Szereg kondensatorów', 'Szereg wartości (E6…E24 i dalsze), do którego zaokrąglane są obliczone kondensatory sieci.', 'pole-audio'),
    ('grafika.tryb.skalowanie', 'Skalowanie charakterystyk', 'Przełącza panel na skalowanie osi obrazu: ustawianie punktów odniesienia i wpisywanie ich wartości.', 'pole-grafika'),
    ('grafika.krok.1', 'Krok 1 – punkt (0,0)', 'Wybierz ten krok i kliknij na obrazie w punkcie przecięcia osi napięcia i prądu, czyli w punkcie (0 V, 0 mA).', 'pole-grafika'),
    ('grafika.krok.2', 'Krok 2 – punkt na osi Ua', 'Wybierz ten krok i kliknij na osi napięcia w miejscu o znanej wartości (najlepiej daleko od zera, np. 300 V); wartość wpisz w polu obok.', 'pole-grafika'),
    ('grafika.krok.3', 'Krok 3 – punkt na osi Ia', 'Wybierz ten krok i kliknij na osi prądu w miejscu o znanej wartości; wartość wpisz w polu obok.', 'pole-grafika'),
    ('grafika.wartosc.napiecie', 'Napięcie punktu na osi Ua', 'Napięcie w woltach, jakie odpowiada punktowi kroku 2 klikniętego na osi napięcia. Dłuższy odcinek od zera daje dokładniejszą skalę.', 'pole-grafika'),
    ('grafika.wartosc.prad', 'Prąd punktu na osi Ia', 'Prąd w miliamperach, jaki odpowiada punktowi kroku 3 klikniętego na osi prądu. Dłuższy odcinek od zera daje dokładniejszą skalę.', 'pole-grafika'),
    ('grafika.wyniki.koniec_pradowy', 'Koniec prądowy', 'Współrzędne (napięcie i prąd) końca prostej obciążenia leżącego przy dużym prądzie – czerwonego kwadratu, który przeciągasz po charakterystyce. Gdy leży na osi albo na lewo od niej, napięcie przyjmowane jest jako 0 V.', 'pole-grafika'),
    ('grafika.wyniki.koniec_napieciowy', 'Koniec napięciowy', 'Współrzędne końca prostej obciążenia leżącego przy dużym napięciu – zielonego kwadratu. Nie może wejść na lewo od końca prądowego.', 'pole-grafika'),
    ('grafika.wyniki.dua', 'ΔUa', 'Różnica napięć anodowych między końcami prostej obciążenia w woltach (amplituda szczytowa napięcia razy dwa).', 'pole-grafika'),
    ('grafika.wyniki.dia', 'ΔIa', 'Różnica prądów anodowych między końcami prostej obciążenia w miliamperach.', 'pole-grafika'),
    ('grafika.wyniki.ra_klasa_a', 'Ra klasa A', 'Rezystancja obciążenia anodowego w kΩ: Ra = ΔUa/ΔIa.', 'pole-grafika'),
    ('grafika.wyniki.raa_klasa_b', 'Raa klasa B', 'Rezystancja anoda–anoda dla stopnia przeciwsobnego w kΩ: Raa = 4·Ra.', 'pole-grafika'),
    ('grafika.wyniki.moc_se_klasa_a', 'Moc SE klasa A', 'Moc wyjściowa stopnia jednotaktowego w klasie A w watach: ΔUa·ΔIa/8.', 'pole-grafika'),
    ('grafika.wyniki.moc_pp_klasa_b', 'Moc PP klasa B', 'Moc wyjściowa stopnia przeciwsobnego w klasie B w watach: cztery razy moc SE.', 'pole-grafika'),
    ('grafika.blokady.ra', 'Zablokuj wartość Ra', 'Utrzymuje nachylenie prostej obciążenia (stałą Ra) podczas przesuwania jej końców.', 'pole-grafika'),
    ('grafika.blokady.amplituda', 'Zablokuj amplitudę ΔIa', 'Utrzymuje stałą różnicę prądów ΔIa podczas przesuwania końców prostej. Razem z blokadą Ra przesuwa prostą sztywno w pionie.', 'pole-grafika'),
    ('grafika.siatka.ia', 'Siatka prądu Ia', 'Włącza rysowanie poziomych linii siatki kontrolnej co zadany prąd, żeby sprawdzić, czy skala zgadza się z podziałką obrazu.', 'pole-grafika'),
    ('grafika.siatka.ia_krok', 'Krok siatki prądu', 'Odstęp poziomych linii siatki kontrolnej w miliamperach.', 'pole-grafika'),
    ('grafika.siatka.ua', 'Siatka napięcia Ua', 'Włącza rysowanie pionowych linii siatki kontrolnej co zadane napięcie.', 'pole-grafika'),
    ('grafika.siatka.ua_krok', 'Krok siatki napięcia', 'Odstęp pionowych linii siatki kontrolnej w woltach.', 'pole-grafika'),
    ('grafika.pamax.moc', 'Moc Pa max', 'Dopuszczalna moc strat w anodzie w watach (z katalogu lampy), dla której rysowana jest krzywa Pa max.', 'pole-grafika'),
    ('grafika.znieksz.Ia1', 'Punkt Ia1', 'Wybiera punkt Ia1 – prąd w punkcie prostej obciążenia między wartością maksymalną a środkiem (dla metody pięciu rzędnych). Dwuklik na prostej ustawia go.', 'pole-grafika'),
    ('grafika.znieksz.Ia0', 'Punkt Ia0', 'Wybiera punkt Ia0 – prąd w środku prostej obciążenia (punkt pracy). Dwuklik na prostej ustawia go.', 'pole-grafika'),
    ('grafika.znieksz.Ia2', 'Punkt Ia2', 'Wybiera punkt Ia2 – prąd w punkcie prostej obciążenia między środkiem a wartością minimalną. Dwuklik na prostej ustawia go.', 'pole-grafika'),
    ('znieksz.tryb.oblicz_dla_pradow', 'Obliczenia dla prądów', 'Przełącza formularz na wpisywanie prądów anodowych w pięciu punktach prostej obciążenia.', 'pole-znieksz'),
    ('znieksz.tryb.oblicz_dla_odcinkow', 'Obliczenia dla odcinków', 'Przełącza formularz na wpisywanie długości odcinków a…g zmierzonych na wykresie.', 'pole-znieksz'),
    ('znieksz.prady.ia_max', 'Ia max', 'Prąd anodowy w miliamperach przy maksymalnym wysterowaniu (+Um), na jednym końcu prostej obciążenia.', 'pole-znieksz'),
    ('znieksz.prady.ia1', 'Ia1', 'Prąd anodowy w mA w punkcie +0,5·Um (w połowie drogi od maksimum do punktu pracy).', 'pole-znieksz'),
    ('znieksz.prady.ia0', 'Ia0', 'Prąd anodowy w mA w punkcie pracy (bez wysterowania).', 'pole-znieksz'),
    ('znieksz.prady.ia2', 'Ia2', 'Prąd anodowy w mA w punkcie −0,5·Um.', 'pole-znieksz'),
    ('znieksz.prady.ia_min', 'Ia min', 'Prąd anodowy w miliamperach przy minimalnym wysterowaniu (−Um), na drugim końcu prostej obciążenia.', 'pole-znieksz'),
    ('znieksz.odcinki.a', 'Odcinek a', 'Długość odcinka a = d + e na prostej obciążenia (dowolna jednostka, ta sama dla wszystkich odcinków).', 'pole-znieksz'),
    ('znieksz.odcinki.b', 'Odcinek b', 'Długość odcinka b = f + g.', 'pole-znieksz'),
    ('znieksz.odcinki.c', 'Odcinek c', 'Długość odcinka c = e + f.', 'pole-znieksz'),
    ('znieksz.odcinki.d', 'Odcinek d', 'Długość pierwszego z czterech kolejnych odcinków między pięcioma punktami prostej (potrzebna do czwartej harmonicznej).', 'pole-znieksz'),
    ('znieksz.odcinki.e', 'Odcinek e', 'Długość drugiego z czterech kolejnych odcinków między pięcioma punktami prostej.', 'pole-znieksz'),
    ('znieksz.odcinki.f', 'Odcinek f', 'Długość trzeciego z czterech kolejnych odcinków między pięcioma punktami prostej.', 'pole-znieksz'),
    ('znieksz.odcinki.g', 'Odcinek g', 'Długość czwartego z czterech kolejnych odcinków między pięcioma punktami prostej.', 'pole-znieksz'),
    ('znieksz.wyniki.h', 'Zniekształcenia całkowite h', 'Zawartość wszystkich harmonicznych (suma geometryczna h2, h3, h4) względem harmonicznej podstawowej, w procentach.', 'pole-znieksz'),
    ('znieksz.wyniki.h2', 'Druga harmoniczna h2', 'Zawartość drugiej harmonicznej względem podstawowej w procentach.', 'pole-znieksz'),
    ('znieksz.wyniki.h3', 'Trzecia harmoniczna h3', 'Zawartość trzeciej harmonicznej względem podstawowej w procentach.', 'pole-znieksz'),
    ('znieksz.wyniki.h4', 'Czwarta harmoniczna h4', 'Zawartość czwartej harmonicznej względem podstawowej w procentach.', 'pole-znieksz'),
    ('cewka.jednostka', 'Jednostka indukcyjności', 'Wybór jednostki dla pola Żądana indukcyjność: µH, mH albo H.', 'pole-cewka-al'),
    ('cewka.sprawdz.zwoje_do_sprawdzenia', 'Zwoje do sprawdzenia', 'Opcjonalnie: liczba zwojów, np. z innego programu. Program poda indukcyjność AL·N² dla tej liczby i jej odchyłkę od żądanej, jako porównanie.', 'pole-cewka-al'),
    ('cewka.sprawdz.indukcyjnosc_dla_zwojow_do_sprawdzenia', 'Indukcyjność dla sprawdzanych zwojów', 'Indukcyjność w mH, jaką daje wpisana liczba zwojów: AL·N².', 'pole-cewka-al'),
    ('cewka.sprawdz.odchylka_od_zadanej', 'Odchyłka sprawdzanych zwojów', 'O ile procent indukcyjność dla sprawdzanych zwojów różni się od żądanej.', 'pole-cewka-al'),
    ('cewka.indukcja.przekroj_rdzenia_ae', 'Przekrój rdzenia Ae', 'Opcjonalnie: przekrój czynny rdzenia w mm² (z katalogu). Potrzebny do obliczenia indukcji szczytowej B = L·I/(N·Ae).', 'pole-cewka-al'),
    ('cewka.indukcja.prad_szczytowy', 'Prąd szczytowy', 'Opcjonalnie: szczytowy prąd cewki w amperach. Razem z przekrojem Ae pozwala obliczyć indukcję w rdzeniu.', 'pole-cewka-al'),
    ('cewka.indukcja.dopuszczalna_indukcja', 'Dopuszczalna indukcja', 'Indukcja w teslach, której nie wolno przekroczyć (ferryty ok. 0,3 T). Po przekroczeniu AL maleje, a rdzeń się nasyca.', 'pole-cewka-al'),
    ('cewka.wyniki.zwoje_dokladnie_n', 'Zwoje dokładnie', 'Liczba zwojów wprost z definicji AL: N = √(L/AL), niezaokrąglona.', 'pole-cewka-al'),
    ('cewka.wyniki.zwoje', 'Zwoje (zaokrąglone)', 'Liczba zwojów zaokrąglona do całkowitej – tyle trzeba nawinąć.', 'pole-cewka-al'),
    ('cewka.wyniki.indukcyjnosc_dla_tej_liczby_zwojow', 'Indukcyjność dla tej liczby zwojów', 'Indukcyjność w mH, jaką daje zaokrąglona liczba zwojów: AL·N².', 'pole-cewka-al'),
    ('cewka.wyniki.odchylka_od_zadanej', 'Odchyłka od żądanej', 'O ile procent indukcyjność dla zaokrąglonej liczby zwojów różni się od żądanej.', 'pole-cewka-al'),
    ('cewka.wyniki.zwoje_dla_granic_tolerancji_al', 'Zwoje dla granic tolerancji AL', 'Zakres liczby zwojów dla skrajnych wartości AL wynikających z podanej tolerancji (większe AL – mniej zwojów).', 'pole-cewka-al'),
    ('cewka.wyniki.indukcja_szczytowa_b', 'Indukcja szczytowa B', 'Indukcja w rdzeniu w teslach: B = L·I/(N·Ae). Porównaj z dopuszczalną indukcją.', 'pole-cewka-al'),
    ('narzedzia.paski.element', 'Rodzaj elementu', 'Czy kody kolorów dotyczą rezystora, czy cewki (kolorowy kod indukcyjności w µH).', 'narzedzia-kody'),
    ('narzedzia.paski.pasek1', 'Pasek 1', 'Kolor pierwszego paska od lewej (od strony, z której pasek leży bliżej brzegu) – pierwsza cyfra wartości.', 'narzedzia-kody'),
    ('narzedzia.paski.pasek2', 'Pasek 2', 'Kolor drugiego paska – druga cyfra wartości.', 'narzedzia-kody'),
    ('narzedzia.paski.pasek3', 'Pasek 3', 'Kolor trzeciego paska – trzecia cyfra wartości (przy 5 i 6 paskach) albo mnożnik (przy 3 i 4 paskach).', 'narzedzia-kody'),
    ('narzedzia.paski.pasek4', 'Pasek 4', 'Kolor czwartego paska – mnożnik (przy 5 i 6 paskach) albo tolerancja (przy 4 paskach).', 'narzedzia-kody'),
    ('narzedzia.paski.pasek5', 'Pasek 5', 'Kolor piątego paska – tolerancja (przy 5 i 6 paskach).', 'narzedzia-kody'),
    ('narzedzia.paski.pasek6', 'Pasek 6', 'Kolor szóstego paska – współczynnik temperaturowy w ppm/K (tylko przy 6 paskach).', 'narzedzia-kody'),
    ('narzedzia.wartosc.tolerancja', 'Tolerancja', 'Dopuszczalne odchylenie rezystancji od wartości nominalnej w procentach; pokazywane kolorem paska tolerancji (brak paska oznacza 20 %).', 'narzedzia-kody'),
    ('narzedzia.wartosc.liczba_paskow', 'Liczba pasków rezystora', 'Ile pasków ma mieć rysunek dla wpisanej wartości: 3 (tolerancja 20 %), 4 (dwie cyfry), 5 (trzy cyfry) albo 6 (trzy cyfry i współczynnik temperaturowy).', 'narzedzia-kody'),
    ('narzedzia.wartosc.tempco', 'Współczynnik temperaturowy', 'Zmiana rezystancji wraz z temperaturą w ppm/K; kodowana szóstym paskiem (np. brązowy = 100 ppm/K). Dotyczy tylko rezystorów 6-paskowych.', 'narzedzia-kody')
